window.PLUS = {"1653":{"k":["모델링 3대 특징: **추상화 · 단순화 · 명확화**(정확화)","모델링은 DB 구축의 사전 작업이면서 **업무를 분석·설명하는 도구**이기도 함"],"w":["추상화는 3대 특징 중 하나. 현실의 공통 성질만 뽑아 일정한 형식으로 표현한다는 설명 그대로라 맞는 보기","","단순화도 3대 특징. 복잡한 현실을 제한된 표기법으로 쉽게 표현한다는 정의와 일치","명확화(정확화)도 3대 특징. 모호함 없이 누구나 같은 뜻으로 읽게 한다는 설명이 정확함"],"t":"보기에 '~만을 위해', '~뿐이다', '반드시 ~만' 같은 한정 표현이 보이면 일단 의심하세요. 모델링 문제의 오답은 대부분 범위를 좁혀 놓은 문장입니다."},"1654":{"k":["데이터 모델은 DB 설계도이면서 **업무 자체를 설명하고 분석하는 수단**","업무 설명용 표기법이 따로 있는 게 아니라 모델이 그 역할을 함"],"w":["업무 정보의 기초가 되는 정보를 약속된 표기법으로 표현하는 것이 모델링의 정의 그대로라 맞음","모델로 DB를 만들고 개발·데이터 관리에 쓰는 것도 모델링의 목적이라 맞음","","모델 자체가 업무 흐름을 설명·분석하는 의미를 가진다는 건 모델링의 중요한 역할이라 맞음"],"t":"'업무 설명은 별도의 ~를 이용한다'처럼 모델의 역할을 다른 것에 떠넘기는 문장은 오답 패턴입니다."},"1655":{"k":["모델링 유의사항 3가지: **중복 · 비유연성 · 비일관성**","대응: 중복 최소화 / 데이터 정의와 프로세스 **분리** / 연관관계 명확히 정의"],"w":["같은 정보를 여러 곳에 저장하지 않게 하는 것은 '중복' 유의사항의 올바른 대응이라 맞음","데이터 정의를 사용 프로세스와 분리해야 업무가 바뀌어도 모델이 흔들리지 않음. '비유연성' 대응책이라 맞음","","데이터 간 연관관계를 명확히 정의하면 일부만 고쳐 생기는 모순을 막음. '비일관성' 대응책이라 맞음"],"t":"유의사항 문제는 '프로그램(프로세스)과 데이터를 떼어 놓는다'가 정답 방향입니다. 연계성을 '높인다', 프로세스에 '맞춘다'는 말이 나오면 거의 오답."},"1656":{"k":["**비유연성**: 업무가 조금만 바뀌어도 모델을 자주 고쳐야 하는 문제","해결책은 데이터 정의를 사용 프로세스와 분리하는 것"],"w":["중복은 같은 정보를 여러 장소에 저장해서 생기는 문제. 지문은 변경에 약한 구조를 말하므로 다름","","비일관성은 중복이 없어도 연관 데이터를 고려하지 않고 일부만 바꿔 서로 모순이 생기는 문제","일관성은 지켜야 할 목표이지 유의사항(피해야 할 것) 이름이 아님"],"t":"지문에 '사소한 업무 변화', '수시로 변경', '유지보수'가 보이면 비유연성, '모순', '상호 연관'이 보이면 비일관성, '여러 장소에 같은 정보'면 중복입니다."},"1657":{"k":["외부 스키마 = **사용자 관점(View)**, 여러 개","개념 스키마 = 모든 관점을 **통합**한 조직 전체 구조, 하나","내부 스키마 = 물리 저장 구조"],"w":["통합된 전체 사용자 관점은 개념 스키마의 정의라 맞음","물리적 저장 구조를 표현하는 건 내부 스키마라 맞음","","논리적 독립성은 외부-개념 사이의 사상으로 보장되므로 맞음"],"t":"'View', '사용자별', '여러 개'는 외부 스키마, '통합', '조직 전체', '하나'는 개념 스키마로 키워드를 짝지어 외우세요."},"1658":{"k":["**개념 스키마**: 모든 사용자 관점을 통합한 조직 전체 DB 구조","DB에 저장되는 데이터와 그 관계, 제약조건을 표현"],"w":["외부 스키마는 각 사용자·응용 프로그램이 보는 일부 관점(서브스키마)이라 '통합'과 반대","","내부 스키마는 레코드 형식·인덱스 같은 물리 저장 구조","'논리 스키마'는 3단계 구조(외부·개념·내부)의 공식 이름이 아님"],"t":"3단계 스키마 보기에 '논리', '물리'라는 이름이 붙어 있으면 함정입니다. 공식 이름은 외부·개념·내부 세 개뿐."},"1659":{"k":["IE 표기에서 엔터티에 **붙은 기호 = 최대**, 먼 기호 = 최소","고객 쪽 `│` → 주문은 고객이 **반드시** 1명, 주문 쪽 `○<` → 고객은 주문이 0건 이상"],"w":["주문 쪽 끝이 까마귀발(여러 개)이라 한 고객이 여러 주문을 낼 수 있음. 맞는 설명","고객 쪽 끝이 필수(│)라 주문에는 반드시 고객이 있어야 함. 맞는 설명","주문 쪽에 ○(선택)가 있어 주문이 없는 고객도 가능. 맞는 설명",""],"t":"관계를 읽을 때는 '읽고 싶은 문장의 목적어 쪽' 끝 기호를 봅니다. '주문은 고객이 있어야 하나?'를 보려면 고객 쪽 끝을 보세요."},"1660":{"k":["ERD는 1976년 **피터 첸**이 제안","작성 순서: 엔터티 도출 → 배치 → 관계 설정 → 관계명 → 관계차수 → 선택사양","가장 중요한 엔터티는 **왼쪽 상단**"],"w":["피터 첸이 1976년 E-R 모델을 만들었다는 건 사실이라 맞음","도출 → 배치 → 관계 설정 → 관계명 순서가 맞음","관계명은 관계를 정확히 읽게 해 주는 핵심 요소라 맞음",""],"t":"배치 문제는 '사람이 글 읽는 방향(왼→오, 위→아래)'만 기억하면 됩니다. 중요한 건 시선이 처음 닿는 왼쪽 위."},"1661":{"k":["엔터티 조건: 업무에 필요, **인스턴스 2개 이상**, **속성 2개 이상**, 관계 1개 이상","속성(이름·주소)은 엔터티가 아니라 엔터티를 설명하는 항목"],"w":["S병원은 하나뿐이라 인스턴스가 1개. 인스턴스가 하나면 엔터티가 될 수 없음","","이름은 환자 한 명 한 명을 설명하는 속성","주소도 환자를 설명하는 속성. 따로 관리할 대상이 아님"],"t":"시나리오형은 '여러 개 있고(인스턴스), 각자 여러 정보(속성)를 가진 명사'를 찾으면 됩니다. '하나뿐인 회사·병원'은 늘 함정."},"1662":{"k":["엔터티는 영속적으로 존재하는 **인스턴스 2개 이상의 집합**","속성 필수, 관계 필수(통계·코드성은 예외), 업무에 필요해야 함"],"w":["속성이 없는 엔터티는 없음. 반드시 속성을 가져야 한다는 건 엔터티 특징 그대로","관계는 1개 이상 있어야 하고, 통계성·코드성 엔터티만 관계를 생략할 수 있다는 예외까지 정확함","","데이터로 있어도 업무에서 쓰지 않으면 엔터티가 아님. 맞는 설명"],"t":"'싱글턴', '하나의 인스턴스로 충분'이 나오면 바로 오답입니다. 엔터티는 집합이라 최소 두 개."},"1663":{"k":["엔터티 특징 6가지: 업무 필요 · 유일 식별자 · 인스턴스 2개↑ · 업무 프로세스가 이용 · 속성 포함 · **관계 1개 이상**"],"w":["","유일한 식별자로 인스턴스를 구분할 수 있어야 함. 엔터티 특징 맞음","생성·조회·수정·삭제 등 업무 프로세스가 이용해야 함. 맞음","속성이 없으면 엔터티가 아님. 반드시 포함해야 한다는 설명 맞음"],"t":"'관계를 가지지 않는다'는 원칙 자체를 부정하는 문장입니다. 예외(코드·통계)가 있다는 것과 원칙이 없다는 건 다릅니다."},"1664":{"k":["발생 시점 분류: **기본(키) · 중심(메인) · 행위**","유무형 분류: 유형 · 개념 · 사건"],"w":["","행위 엔터티는 두 개 이상 부모에서 발생하는 이력·내역. 발생 시점 분류에 포함","중심 엔터티는 기본 엔터티에서 발생한 업무 중심 거래. 포함","기본 엔터티는 독립적으로 생성되는 엔터티. 포함"],"t":"발생 시점은 '기중행', 유무형은 '유개사'로 외우세요. '관계 엔터티', '교차 엔터티'는 두 분류 어디에도 없습니다."},"1665":{"k":["엔터티 이름: 현업 용어 · **약어 지양** · 단수 명사 · 전체에서 유일 · 생성 의미대로"],"w":["","현업 용어를 써야 업무 담당자와 소통이 됨. 맞는 원칙","같은 이름이 둘이면 혼란이 생기므로 유일해야 함. 맞는 원칙","고객이 주문한 것은 '주문'처럼 생성 의미대로 짓는 게 원칙. 맞음"],"t":"이름 짓기 문제에서 '약어'는 엔터티든 속성이든 늘 '가급적 쓰지 않는다'가 정답입니다."},"1666":{"k":["**속성**: 업무에 필요한, 의미상 더 이상 분리되지 않는 **최소 데이터 단위**"],"w":["도메인은 속성이 가질 수 있는 값의 범위(타입·크기·제약)","","엔터티는 속성들을 가진 인스턴스의 집합. 최소 단위가 아님","관계는 엔터티와 엔터티 사이의 연관"],"t":"'최소 단위', '더 이상 분리되지 않는'이 나오면 속성, '값의 범위'가 나오면 도메인입니다."},"1667":{"k":["한 인스턴스에서 한 속성은 **값 하나만** 가짐","값이 여러 개면 별도 엔터티로 분리 (1차 정규화 원리)"],"w":["속성은 엔터티를 자세하고 구체적으로 설명하는 정보라 맞음","엔터티는 속성 두 개 이상을 가지는 게 원칙이라 맞음","","같은 성격의 값들이 모인 것이라 속성도 집합으로 볼 수 있음. 맞음"],"t":"속성 문제에서 '하나 이상의 값', '여러 값'이 나오면 1정규형 위배 = 오답으로 바로 연결하세요."},"1668":{"k":["**2차 정규화** = 부분 함수 종속 제거 (PK 일부에만 종속된 속성을 떼어냄)","복합 PK(주문번호, 상품코드)에서 상품명·가격은 상품코드에만 종속"],"w":["1차 정규화는 반복 속성·다중값을 없애 원자값으로 만드는 것","","3차 정규화는 일반 속성끼리의 이행 종속 제거","4차 정규화는 다치 종속 제거"],"t":"정규화 전후 그림이 나오면 '떼어 나간 속성이 무엇에 종속됐는지'만 보세요. PK 일부 → 2차, 일반 속성 → 3차."},"1669":{"k":["속성 특성 분류: **기본**(업무에서 바로) · **설계**(설계하며 만든 코드·일련번호) · **파생**(계산된 값)","파생 속성은 조회 성능을 위해 저장하지만 정합성 관리 부담 → 최소화"],"w":["","기본 속성은 업무 분석에서 바로 나온 원래 속성(단가, 이름)","설계 속성은 업무에 없던 걸 설계 중 만든 속성(상태코드, 일련번호)","PK 속성은 구성 방식 분류(PK·FK·일반)에 속하는 이름이라 특성 분류와 다름"],"t":"'계산', '빠른 조회를 위해 저장'은 파생 속성, '코드', '일련번호'는 설계 속성입니다."},"1670":{"k":["**도메인**: 속성이 가질 수 있는 값의 범위","데이터 타입 · 크기(길이) · 제약사항(범위, 허용 값)"],"w":["시스템 카탈로그는 DBMS가 테이블·컬럼 정보 같은 메타데이터를 보관하는 곳","용어 사전은 표준 용어와 뜻을 정리한 사전","속성 사전은 속성 목록과 설명을 정리한 문서. 값의 범위 정의를 가리키는 용어는 아님",""],"t":"'~사이의 값', '~자리 이내 문자열'처럼 범위와 형식을 정하는 문장은 도메인입니다."},"1671":{"k":["속성명: 현업 용어 · 서술식 금지 · 약어 지양 · **전체 모델에서 유일**"],"w":["약어를 남발하면 뜻이 모호해져 소통이 어려워짐. 가급적 제한한다는 원칙이 맞음","'처음 가입한 날짜' 같은 서술식 이름 대신 '가입일자'처럼 써야 함. 맞음","","용어가 겹칠 때 해당 업무에서 자주 쓰는 이름을 고른다는 건 맞는 방법"],"t":"'이름', '주소'처럼 여러 엔터티에 같은 속성명을 쓰는 건 일관성처럼 보여도 오답입니다. 직원명·고객명처럼 유일하게."},"1672":{"k":["UML **연관관계** = 실선 · 존재적 · 소스코드에서 **멤버변수**로 선언","UML **의존관계** = 점선 · 행위적 · 오퍼레이션 **파라미터**로 사용","ERD는 존재·행위 관계를 구분하지 않음"],"w":["ERD는 두 관계를 같은 선으로 그려 구분하지 않는다는 설명 맞음","UML에서 연관은 실선, 의존은 점선으로 다르게 표현. 맞음","연관은 늘 쓰는 존재적 관계, 의존은 행위에 따른 관계. 맞음",""],"t":"'연관 = 멤버변수(늘 들고 있음)', '의존 = 파라미터(필요할 때 받음)'로 외우면 바뀐 보기를 바로 잡습니다."},"1673":{"k":["관계 표기 3요소: **관계명 · 관계차수 · 관계선택사양**(관차선)","관계 분류: 존재적(부서-사원 소속) / 행위적(주문-배송)"],"w":["관계는 존재에 의한 관계와 행위에 의한 관계로 나뉨. 맞는 설명","","사원이 부서에 '소속'되는 건 존재 자체로 맺어지는 관계라 존재적 관계의 대표 예","배송은 주문이라는 행위가 있어야 생기므로 행위에 의한 관계. 맞음"],"t":"'식별성', '관계 인덱스', '관계 유형' 같은 말이 3요소 자리에 끼어 있으면 오답입니다. 3요소는 '관차선'."},"1674":{"k":["**물리적 독립성**: 내부 스키마(파일·색인 구조)가 바뀌어도 개념·외부 스키마와 응용 프로그램에 영향 없음","**논리적 독립성**: 개념 스키마가 바뀌어도 외부 스키마에 영향 없음"],"w":["논리적 독립성은 개념 스키마(논리 구조) 변경으로부터 외부 스키마를 보호하는 것. 지문은 파일·색인 같은 물리 구조 변경 이야기","","'개념적 독립성'은 존재하지 않는 용어","'내부적 독립성'도 없는 용어. 독립성은 논리적·물리적 두 가지뿐"],"t":"'파일 구조', '색인(인덱스)', '저장 장치'가 바뀌는 이야기면 물리적, '테이블 구조', '컬럼 추가'가 바뀌는 이야기면 논리적 독립성입니다."},"1675":{"k":["**관계차수(Cardinality)**: 한 인스턴스가 상대 인스턴스 몇 개와 연결되나 (1:1, 1:M, M:N)","선택사양(Optionality): 필수냐 선택이냐"],"w":["관계명은 관계에 붙이는 이름(소속된다, 주문한다)","","관계선택사양은 관계가 반드시 있어야 하는지(필수) 없어도 되는지(선택)를 나타냄","'관계정의'는 관계 표기 구성요소가 아님"],"t":"'몇 개', '참여자의 수', '1:M'이 나오면 차수, '반드시', '없을 수도'가 나오면 선택사양입니다."},"1676":{"k":["관계 확인 4가지: 연관규칙 · 정보의 조합 · 규칙 서술 · 관계를 이어 주는 **동사(Verb)**","엔터티는 명사에서, 관계는 동사에서 찾음"],"w":["두 엔터티 사이에 관심 있는 연관규칙이 있는지 확인하는 건 맞는 항목","두 엔터티 정보가 조합되어 쓰이는지 확인하는 것도 맞는 항목","","업무기술서·장표에 관계연결 규칙이 서술됐는지 보는 것도 맞는 항목"],"t":"명사 → 엔터티(또는 속성), 동사 → 관계. 이 짝만 기억하면 '명사(Noun)'로 바꿔 놓은 함정을 바로 잡습니다."},"1677":{"k":["관계 도출 확인 사항 **4가지 전부**: 연관규칙 · 정보 조합 · 규칙 서술 · 동사"],"w":["(라) 관계를 이어 주는 동사가 있는지도 확인 항목이라 빠지면 안 됨","(다) 업무기술서에 관계 규칙이 서술됐는지도 확인 항목","(나) 두 엔터티 사이 정보의 조합 발생 여부도 확인 항목",""],"t":"'모두 고르시오'에서 네 항목이 전부 표준 문구 그대로면 전부 맞는 경우가 많습니다. 하나만 이상한 단어가 섞였는지부터 찾아보세요."},"1678":{"k":["주식별자 4특징: **유일성 · 최소성 · 불변성 · 존재성**","(가) 유일성 (나) 최소성 (다) 불변성 (라) 존재성"],"w":["(라) 존재성(값이 반드시 있어야 함)도 고려해야 함","(가) 유일성이 빠짐. 가장 기본이 되는 특징","(가) 유일성이 빠짐",""],"t":"주식별자 4특징은 '유최불존'. 보기 네 개가 각각 하나씩 설명하고 있으면 답은 '모두'입니다."},"1679":{"k":["식별자 분류 4축: 대표성(주/보조) · 생성(내부/외부) · 속성 수(단일/복합) · 대체 여부(**본질/인조**)","사번은 업무에서 원래 쓰는 값 → 본질식별자"],"w":["사번은 사원을 대표하는 식별자라 주식별자 맞음","속성 하나(사번)로 식별하므로 단일식별자 맞음","다른 엔터티에서 받아온 게 아니라 사원 안에서 생긴 값이라 내부식별자 맞음",""],"t":"인조식별자는 '업무에 없던 일련번호를 일부러 만든 것'입니다. 사번·주문번호처럼 업무에서 실제로 쓰는 번호는 본질식별자로 봅니다."},"1680":{"k":["주식별자는 **유일성**을 보장해야 함","이름·명칭·내역처럼 중복될 수 있는 값은 주식별자로 부적절"],"w":["사원번호는 사원마다 하나씩 부여돼 유일하므로 식별자로 적절","","주민번호도 사람마다 유일해 식별자로 쓸 수 있음","업무에 없던 일련번호(인조식별자)도 유일성만 지키면 식별자로 쓸 수 있음"],"t":"식별자 보기에 '이름', '명', '내역'이 들어가 있으면 동명이인부터 떠올리세요."},"1681":{"k":["**존재성**: 주식별자가 지정되면 반드시 값이 있어야 함 (NULL 불가)","유일성 · 최소성 · 불변성 · 존재성"],"w":["모든 인스턴스를 유일하게 구분한다는 유일성 설명이 정확함","","한번 정한 식별자 값은 바뀌지 않아야 한다는 불변성 설명이 정확함","유일성을 만족하는 최소 속성 수라는 최소성 설명이 정확함"],"t":"PK와 NULL이 같은 문장에 나오면 거의 항상 오답입니다. PK = NOT NULL + UNIQUE."},"1682":{"k":["**식별 관계**는 부모 PK가 자식 PK까지 내려가서 조인을 줄일 수 있음","**비식별 관계**를 쓰는 경우: 부모 없이 자식 생성 / 부모가 먼저 소멸 / 자식에 독립 PK가 유리"],"w":["부모 없이 자식이 먼저 생길 수 있으면 자식 PK에 부모 PK를 넣을 수 없으므로 비식별 관계가 맞음","부모가 먼저 지워져도 자식이 남아야 하면 비식별 관계로 연결해야 함. 맞음","","상속받은 PK가 길어지는 것보다 독립 PK가 유리하면 비식별 관계. 맞음"],"t":"'조인을 줄인다', 'SQL을 단순하게(조인 경로 단축)'는 식별 관계의 장점입니다. 비식별 이유로 나오면 오답."},"1683":{"k":["대표성: **주식별자**(대표) / **보조식별자**(유일하지만 대표 X)","대체 여부: **본질식별자**(업무 의미) / 인조식별자(만든 번호)","생성: 내부식별자 / **외부식별자**(다른 엔터티에서 상속)"],"w":["(가)는 대표성이 있으니 보조가 아니라 주식별자. (나)도 '실질식별자'라는 분류는 없음","(가)는 주식별자, (나)는 보조식별자여야 함. 자리를 바꿔 놓음","","(다) '업무적으로 의미가 부여된' 식별자는 인조가 아니라 본질식별자"],"t":"짝짓기 문제는 확실한 것 하나로 보기를 지워 나가세요. '다른 엔터티로부터 상속' = 외부식별자만 알아도 ①②가 바로 빠집니다."},"1684":{"k":["**도메인** = 속성이 가질 수 있는 값의 범위","데이터 타입 · 크기 · 제약사항이 모두 도메인 안에 들어감"],"w":["제약사항은 도메인을 정할 때 지정하는 요소 중 하나일 뿐, 범위 전체를 부르는 이름이 아님","","데이터 타입도 도메인의 구성요소 중 하나","데이터 크기도 도메인의 구성요소 중 하나"],"t":"타입·크기·제약은 '부분', 도메인은 그걸 다 합친 '전체'입니다. 부분과 전체를 묻는 문제로 보면 쉽습니다."},"1685":{"k":["특성 분류: **기본**(업무 분석에서 바로) · **설계**(설계하며 만듦) · **파생**(계산·변형)","구성 분류: PK · FK · **일반** 속성 → 분류 기준이 다름"],"w":["","㉡ 설계하며 만든 속성은 설계 속성, ㉢ 계산으로 만든 속성은 파생 속성. 일반 속성은 다른 분류","㉠은 기본 속성. 일반 속성은 PK·FK가 아닌 속성을 가리키는 구성 분류 용어","㉠ 자리에 일반 속성은 맞지 않음. 업무분석으로 바로 정의한 건 기본 속성"],"t":"'일반 속성'은 PK·FK와 짝을 이루는 말입니다. 기본·설계·파생 문제에 섞여 나오면 거의 함정."},"1686":{"k":["**후보키**: 모든 속성을 결정하면서(유일성) 군더더기가 없는(최소성) 속성 집합","함수 종속을 따라가며 결정되는 속성(폐포)을 넓혀 보면 판단됨"],"w":["d → ab, ab → cde이므로 d 하나로 모든 속성이 결정됨. 후보키 맞음","ab → cde로 바로 전체가 결정됨. 후보키 맞음","","e → b이므로 ae가 있으면 ab를 얻고, ab → cde로 전체 결정. 후보키 맞음"],"t":"후보키 판정은 '이 속성들로 시작해서 화살표를 타면 전부 나오나?'만 해 보면 됩니다. ac처럼 출발할 화살표가 없으면 바로 탈락."},"1687":{"k":["**2NF 위배** = 부분 함수 종속: 복합 PK의 일부(상품번호)만으로 결정되는 속성(상품명)이 있음"],"w":["한 칸에 값이 하나씩만 있으니 1NF는 만족","","3NF를 따지기 전에 2NF부터 깨져 있으므로 '만족하지 않는 정규형'은 2NF","4NF는 다치 종속 문제로, 2NF도 안 되는 상태에서 볼 단계가 아님"],"t":"'만족하지 않는 정규형'은 가장 낮은 단계에서 답이 정해집니다. 아래부터 차례로 확인하세요."},"1688":{"k":["관서번호 → 관리점번호, 관서명, 상태, 관서등록일자 = PK **일부**에 종속 → **2차 정규화**","분리한 테이블의 PK는 결정자(관서번호) 하나"],"w":["2차 정규화는 맞지만, 떼어낸 테이블에 납부자번호까지 PK로 남기면 부분 종속이 그대로 남음","부분 종속 제거는 3차가 아니라 2차. PK에 납부자번호가 남은 것도 틀림","","PK 구성은 맞지만 부분 종속 제거를 3차 정규화라고 한 것이 틀림"],"t":"정규화 결과 테이블의 PK는 항상 '결정자'입니다. FD 왼쪽에 있는 것만 PK로 가져가면 됩니다."},"1689":{"k":["정규화: 중복 제거 → 용량 감소, **입력·수정·삭제 성능 향상**","조회는 조인이 늘어 **느려질 수도** 있음 (보장 X)","반정규화도 조회 성능을 항상 올리지는 않음"],"w":["중복 속성을 없애므로 저장 용량이 줄어듦. 맞음","중복이 없어 한 곳만 고치면 되므로 일반적인 데이터 처리(DML) 성능은 좋아짐. 맞음","반정규화가 늘 빠른 건 아니고, 정규화로 테이블이 작아져 오히려 빨라지는 경우도 있음. 맞음",""],"t":"성능 문제에서 '항상', '보장'이 붙은 문장은 거의 오답입니다. 정규화·반정규화 모두 상황에 따라 달라집니다."},"1690":{"k":["같은 성격의 컬럼이 1~9처럼 **반복**되면 1NF 위배 → 행으로 분리(1차 정규화)","컬럼마다 인덱스를 만들면 DML 성능 저하"],"w":["컬럼 단위로 반복되는 그룹이 있다는 건 1NF를 '위반'한 상태. 1NF라고 할 수 없음","조건이 여러 컬럼에 OR로 걸리면 PK 인덱스로는 해결 안 됨. 인덱스 없는 컬럼 하나 때문에 전체를 읽게 됨","반복 속성은 2NF가 아니라 1NF 문제. '이전종속'도 맞지 않는 용어",""],"t":"'코드1, 코드2, …코드9'처럼 번호 붙은 컬럼 묶음을 보면 1차 정규화부터 떠올리세요."},"1691":{"k":["1NF: 반복 그룹(LAB실 이용 1~4, 대출도서 여러 권) 분리","2NF: 부분 종속(도서 정보) 분리","3NF: 이행 종속(학과명, 승인교수명) 분리 → 학과·학생·교수·LAB실이용·대출·대출도서·도서 **7개**"],"w":["학과나 교수처럼 이행 종속으로 떨어져 나가야 할 엔터티를 빼먹은 개수","도서 또는 대출도서 분리를 빠뜨린 개수","","필요 이상으로 쪼갠 개수. 대출자 정보는 학생·교수로 이미 표현됨"],"t":"엔터티 개수 세기는 '반복 묶음 → 새 엔터티', '이름(명)이 코드에 딸려 있음 → 새 엔터티' 두 가지만 체크하며 세면 됩니다."},"1692":{"k":["**3NF** = 2NF를 만족하면서 PK가 아닌 속성이 PK에 **이행적으로 종속되지 않음**","각 단계는 이전 단계를 전제로 함"],"w":["3NF 정의의 전제는 1NF가 아니라 2NF","㉠ 자리는 2NF여야 함. 1NF에서 바로 3NF로 가지 않음","","순서가 뒤바뀜. ㉠이 2NF, ㉡이 3NF"],"t":"정의 문장에 '이행'이 나오면 3NF, '부분'이 나오면 2NF, '원자값'이면 1NF입니다."},"1693":{"k":["정규화는 **논리** 데이터 모델링 단계의 활동","1NF 원자값 → 2NF 주식별자 전체에 종속 → 3NF 이행 종속 없음"],"w":["","1NF는 모든 속성이 인스턴스마다 값 하나만 가진다는 뜻이라 맞음","3NF는 2NF를 전제로 하므로 일반속성이 주식별자 전체에 종속돼 있다는 말이 맞음","반정규화는 중복을 허용해 성능을 노리지만 늘 빨라지는 건 아님. 맞음"],"t":"단계 짝: 개념 = ERD 처음 작성, 논리 = 정규화, 물리 = 반정규화·인덱스. 정규화 앞에 '개념'이 붙으면 오답 신호입니다."},"1694":{"k":["**식별 관계**: 부모 식별자 → 자식 **식별자(PK)**에 포함","**비식별 관계**: 부모 식별자 → 자식 **일반속성**","관계 = 식별자 상속, 조인 = 상속된 속성(매핑키)으로 결합"],"w":["조인은 상속받은 속성을 매핑키로 써서 데이터를 결합하는 것. 맞는 정의","","관계를 맺는다는 건 식별자를 상속시켜 나중에 그 키로 결합하겠다는 뜻. 맞음","주문.고객번호 = 고객.고객번호로 연결하므로 조인키는 고객번호. 맞음"],"t":"식별/비식별을 바꿔 쓰는 함정이 가장 흔합니다. '식별 관계 = 자식 PK가 된다'만 확실히 잡아 두세요."},"1695":{"k":["**2NF**: 일반속성이 주식별자 **전체**에 종속 (부분 종속 없음)"],"w":["1NF는 모든 속성이 원자값(하나의 값)을 가지는 것","","3NF는 일반속성끼리의 이행 종속이 없는 것","BCNF는 모든 결정자가 후보키인 것"],"t":"'전체에 종속' = 2NF, '이행 종속 없음' = 3NF, '결정자가 후보키' = BCNF. 정의 문장의 핵심 단어 하나로 고르면 됩니다."},"1696":{"k":["학번 → 지도교수명, 학번 → 학과명: 복합 PK(학번, 과목코드)의 **일부**에 종속 → 2NF 위배","현재 상태 = 1NF, 다음 작업 = **2차 정규화**"],"w":["","부분 종속이 남아 있어 2NF가 아님. 따라서 '2차 정규형'이라 할 수 없음","2NF도 못 갖췄으니 3NF는 더욱 아님","BCNF는 3NF보다 위 단계라 해당 없음"],"t":"FD 목록에서 왼쪽이 PK 일부(학번만)인 줄이 하나라도 있으면 '1정규형, 2차 정규화 대상'으로 바로 답이 나옵니다."},"1697":{"k":["한 칸에 '10,11', '노래,댄스'처럼 값이 **여러 개** → 1NF 위배","1차 정규화로 고객-취미를 행 단위로 분리"],"w":["","2차 정규화(부분 종속)는 1NF를 만족한 뒤에 따질 문제","3차 정규화는 이행 종속 문제라 아직 해당 없음","4차 정규화는 다치 종속 문제라 해당 없음"],"t":"표 안에 쉼표로 이어진 값이 보이면 생각할 것 없이 1차 정규화입니다."},"1698":{"k":["NULL = 모르는 값, 값의 부재","**0도, 공백('')도 아님** (Oracle은 ''를 NULL로 저장하지만 개념상 다름)","IS NULL 외 비교는 모두 UNKNOWN"],"w":["아직 정해지지 않은 '모르는 값'이라는 설명이 맞음","값이 없다는 '부재'의 의미도 맞음","","= , <>, > 같은 비교는 모두 UNKNOWN을 돌려줌. 맞음"],"t":"NULL 정의 문제에서 '0', '공백', '빈 문자열'과 같다고 하면 무조건 오답입니다."},"1699":{"k":["(사번, 부서) PK에서 부서 → 사무실 = **부분 종속** → 분리 = **2차 정규화**","정규화하면 조인이 필요해 조회 성능은 떨어질 수 있음"],"w":["","PK 일부(부서)에 종속된 사무실을 떼어냈으니 2차 정규화가 맞음","(B)의 두 테이블 모두 이행 종속이 없어 3NF까지 만족. 맞음","사번으로 사무실을 찾으려면 두 테이블을 조인해야 하므로 성능 저하가 맞음"],"t":"원래 테이블에 다중값이 없었다면 '제1정규화 수행'은 성립하지 않습니다. 무엇이 떨어져 나갔는지로 단계를 판단하세요."},"1700":{"k":["**원자성**: 묶인 작업은 전부 수행되거나 전혀 수행되지 않음","한 트랜잭션으로 묶고 **끝에서 한 번** COMMIT","중간에 장애 → 이미 한 작업을 UNDO(롤백)"],"w":["반드시 함께 처리돼야 하므로 하나의 트랜잭션으로 묶는 게 맞음","","'모두 수행 또는 모두 미수행'은 원자성의 정의 그대로","A만 끝나고 장애가 나면 A를 되돌려야 원자성이 지켜짐. 맞음"],"t":"'각각 커밋'은 트랜잭션을 두 개로 쪼갠다는 뜻입니다. 함께 처리해야 하는 작업 문제에서 나오면 오답."},"1701":{"k":["NULL + 숫자 = **NULL**","NULL과 비교 = **UNKNOWN** (NULL = NULL도 TRUE 아님)","집계함수는 NULL을 **제외** (0으로 치지 않음)"],"w":["","비교 결과는 NULL이 아니라 UNKNOWN(알 수 없음)","NULL = NULL도 UNKNOWN이라 WHERE에서 걸러짐. TRUE가 아님","SUM·AVG 등은 NULL을 0으로 바꾸지 않고 계산에서 아예 뺌. AVG의 분모도 줄어듦"],"t":"NULL 규칙 세 줄: 계산하면 NULL, 비교하면 UNKNOWN, 집계하면 제외. 이 셋만 구분하면 NULL 문제는 거의 다 풀립니다."},"1702":{"k":["인조식별자: 본질식별자가 복잡할 때 만듦","단점: **중복 데이터를 막기 어려움**, **추가 인덱스** 필요","편하다고 무조건 쓰지 않고 필요할 때만"],"w":["본질식별자가 여러 속성으로 복잡해지면 일련번호로 대신하는 경우가 많음. 맞음","일련번호가 다르면 같은 내용이 두 번 들어가도 PK가 막지 못함. 맞음","본질 속성으로 조회하거나 중복을 막으려면 그쪽에 인덱스를 따로 만들어야 함. 맞음",""],"t":"식별자 문제에서 '되도록 사용하는 것이 바람직'처럼 한쪽을 무조건 권하는 문장은 오답일 가능성이 큽니다."},"1703":{"k":["**DCL**: GRANT, REVOKE (권한)","DML: SELECT·INSERT·UPDATE·DELETE·MERGE / DDL: CREATE·ALTER·DROP·RENAME·TRUNCATE / TCL: COMMIT·ROLLBACK·SAVEPOINT"],"w":["INSERT는 데이터를 넣는 DML","RENAME은 객체 이름을 바꾸는 DDL","COMMIT은 트랜잭션을 확정하는 TCL",""],"t":"DCL은 딱 두 개, GRANT와 REVOKE만 외우면 됩니다. 나머지는 지우는 방식으로 풀어도 충분."},"1704":{"k":["DML 4종: INSERT(입력) · **UPDATE(수정)** · DELETE(삭제) · SELECT(조회)"],"w":["","SELECT는 조회만 하고 값을 고치지 않음","ALTER는 데이터가 아니라 테이블 구조를 바꾸는 DDL","REVOKE는 권한을 회수하는 DCL"],"t":"'데이터 값'을 바꾸면 UPDATE, '테이블 구조'를 바꾸면 ALTER. 무엇을 바꾸는지로 구분하세요."},"1705":{"k":["**TCL**: COMMIT · ROLLBACK · SAVEPOINT","DML 결과를 트랜잭션 단위로 확정·취소"],"w":["DDL은 테이블 같은 구조를 정의하는 명령","DML은 데이터를 조회·조작하는 명령","","'TML'이라는 SQL 분류는 없음"],"t":"'트랜잭션'이라는 단어가 지문에 나오면 TCL입니다. 일부 교재에서 DCL로 묶기도 한다는 말까지 지문에 나와도 답은 TCL."},"1706":{"k":["SELECT 필수 절: **SELECT, FROM** (Oracle)","상수만 조회할 때도 `FROM DUAL`","WHERE·GROUP BY·ORDER BY는 선택"],"w":["WHERE는 조건이 필요할 때만 쓰는 선택 절. 맞음","DISTINCT로 중복 행을 한 건으로 줄일 수 있음. 맞음","","SELECT 절에 스칼라 서브쿼리를 쓸 수 있음. 맞음"],"t":"Oracle 기준 문제에서 FROM이 빠진 SELECT는 오류입니다. SQL Server는 FROM 없이 되지만 시험은 Oracle 기준."},"1707":{"k":["SELECT = DML","GRANT = DCL, DROP·ALTER = DDL"],"w":["","GRANT는 권한을 주는 DCL. TCL은 COMMIT·ROLLBACK·SAVEPOINT","DROP은 객체를 지우는 DDL","ALTER는 구조를 바꾸는 DDL"],"t":"SELECT를 DQL로 따로 보는 교재도 있지만, 보기가 DML·DDL·DCL·TCL 네 가지로만 나오면 SELECT는 DML입니다."},"1708":{"k":["**DDL**: CREATE · ALTER · DROP · RENAME · TRUNCATE (구조 정의)","GRANT는 DCL"],"w":["CREATE는 객체를 만드는 DDL","","ALTER는 구조를 바꾸는 DDL","DROP은 객체를 지우는 DDL"],"t":"'구조'라는 단어가 나오면 DDL. 그 범주에 권한 명령(GRANT, REVOKE)이 섞여 있으면 그게 답입니다."},"1709":{"k":["**WHERE**: 행 조건 / HAVING: 그룹 조건 / GROUP BY: 묶기 / ORDER BY: 정렬"],"w":["","GROUP BY는 같은 값끼리 묶는 절이지 조건을 거는 절이 아님","ORDER BY는 결과를 정렬하는 절","HAVING도 조건이지만 GROUP BY로 묶은 그룹에 거는 조건"],"t":"개별 행을 거르면 WHERE, 묶은 그룹을 거르면 HAVING. '원하는 데이터만'처럼 행 단위면 WHERE입니다."},"1710":{"k":["집계함수는 **WHERE에 쓸 수 없음** → HAVING으로","WHERE는 GROUP BY보다 먼저 실행되어 그 시점엔 그룹이 없음"],"w":["SELECT의 AVG는 GROUP BY DEPTNO와 함께 쓰여 문제없음","FROM EMP는 문법상 문제없음","","GROUP BY DEPTNO는 SELECT의 DEPTNO와 맞아 문제없음"],"t":"실행 순서(FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY)를 떠올리면, WHERE 시점에 AVG를 계산할 그룹이 없다는 게 바로 보입니다."},"1711":{"k":["SUM은 NULL을 **빼고** 더함","더할 값이 전부 NULL이면 SUM 결과는 **NULL**","NULL + 숫자 = NULL"],"w":["첫 번째는 COL2 합 60 + COL3 합 30 = 90. 60은 COL2만 더한 값","첫 번째가 90이 아님. 두 번째 결과 NULL은 맞음","","두 번째는 COL1 > 0인 행이 30 하나뿐이고 그 행의 COL2가 NULL → SUM(COL2) = NULL, NULL + 20 = NULL. 20이 아님"],"t":"SUM(A) + SUM(B) 문제는 각 SUM을 따로 계산한 뒤 더하세요. 한쪽 SUM이 NULL이 되는 순간 전체가 NULL입니다."},"1712":{"k":["NULL 비교는 **IS NULL / IS NOT NULL**만","`= NULL`, `<> NULL`, `!= NULL`은 항상 UNKNOWN → 0건"],"w":["","<> NULL은 UNKNOWN이라 어떤 행도 나오지 않음","!= NULL도 같은 이유로 0건","'NOT NULL'은 제약조건 문법이지 WHERE 조건 문법이 아님. IS가 빠져 오류"],"t":"NULL 앞에는 반드시 IS가 붙어야 합니다. 비교 연산자 기호가 NULL 앞에 있으면 결과는 0건이에요."},"1713":{"k":["**Oracle**: ''(빈 문자열)를 **NULL로 저장** → `= ''`로 못 찾고 IS NULL로 찾음","**SQL Server**: ''는 길이 0인 문자 → `= ''`로 찾히고 IS NULL로는 안 찾힘","문자 컬럼 = 숫자 비교 시 컬럼 쪽이 숫자로 변환 → 숫자로 못 바꾸는 값이 하나라도 있으면 오류"],"w":["VARCHAR2 컬럼을 숫자 1과 비교하면 모든 행의 값을 숫자로 바꿔 보는데, 'A01'처럼 숫자로 못 바꾸는 값이 하나라도 있으면 오류. '001' 같은 값이 '하나 있다'고 되는 게 아니라 '전부' 숫자 형식이어야 함","Oracle에서 ''를 넣으면 공백 문자가 아니라 NULL이 저장됨","Oracle에서는 ''가 NULL이라 `서비스명 = ''`는 NULL과의 비교 → 0건. IS NULL로 찾아야 조회됨",""],"t":"'' 문제는 DBMS 이름부터 확인하세요. Oracle이면 '' = NULL, SQL Server면 '' ≠ NULL. 이 한 줄로 보기 두세 개가 정리됩니다."},"1714":{"k":["**LTRIM(문자, 집합)**: 왼쪽부터 집합에 속한 문자를 지우다가 **다른 문자를 만나면 멈춤**","오른쪽은 RTRIM, 양쪽은 TRIM"],"w":["LOWER는 모든 글자를 소문자로 바꿔 'sql expert'. 맞음","UPPER는 모든 글자를 대문자로 바꿔 'SQL EXPERT'. 맞음","'A'의 아스키코드는 65. 맞음",""],"t":"TRIM 계열 문제는 L(왼쪽)·R(오른쪽)·양쪽 중 어느 쪽인지만 보면 됩니다. 결과 문자열 끝에 지워질 문자가 남아 있는지 확인하세요."},"1715":{"k":["DATE 컬럼은 **시·분·초까지** 저장됨","`TO_DATE('201501','YYYYMM')` = 2015-01-01 **00:00:00** 한 시점","'1월 전체'는 범위 조건(>= 1/1 AND < 2/1)이나 TO_CHAR(…, 'YYYYMM')으로"],"w":["1월 1일 0시 ~ 1월 31일 23:59:59 범위와 가입일시 조건이라 1월 전체를 찾음. ②③과 결과 같음","1월 1일 이상 2월 1일 미만 범위는 1월 전체와 같음. 다중 컬럼 IN도 같은 조건","TO_CHAR로 'YYYYMM'이 201501인 행 = 1월 전체. 결과 같음",""],"t":"날짜를 = 로 비교하는 보기는 '그 순간 딱 하나'만 찾습니다. 기간을 묻는 문제에서 = 가 보이면 그 보기가 다른 결과일 가능성이 큽니다."},"1716":{"k":["집계함수는 **NULL 제외**, WHERE에 **못 씀**","GROUP BY에서 SELECT 별칭 **사용 불가** (GROUP BY가 SELECT보다 먼저 실행)","HAVING은 보통 GROUP BY 뒤에 씀"],"w":["집계함수는 NULL인 행을 빼고 계산함. '포함하여'가 틀림","GROUP BY는 SELECT보다 먼저 실행돼 그 시점엔 별칭이 없음. 시험 기준 사용 불가","집계함수는 WHERE에 올 수 없고 HAVING에서 씀",""],"t":"별칭 문제는 '실행 순서상 별칭이 만들어진 뒤인가?'만 따지면 됩니다. SELECT 뒤에 실행되는 건 ORDER BY 하나뿐."},"1717":{"k":["`LENGTH(C1) - LENGTH(REPLACE(C1, CHR(10)))` = 줄바꿈 **개수**","+1 하면 **줄 수**","REPLACE 세 번째 인자 생략 = 삭제"],"w":["행 수(2건)를 센 값. 문제는 줄 수의 합을 묻고 있음","줄바꿈 개수만 더한 값(1 + 2). 행마다 +1을 해야 줄 수가 됨","","줄 수를 행마다 하나씩 더 센 값. 'A↵A'는 2줄, 'B↵B↵B'는 3줄이라 합 5"],"t":"'전체 길이 − 특정 문자를 지운 길이' 패턴은 그 문자의 개수를 세는 공식입니다. 이 공식은 다른 문제에도 자주 나와요."},"1718":{"k":["Oracle 날짜 연산 단위는 **일**","1/24 = 1시간, 1/24/60 = 1분, 1/24/60/60 = 1초","1/24/(60/10) = 1/24/6 = **10분**"],"w":["1시간 1분을 더한 값. 1/24/6은 1시간이 아니라 10분","5분을 더한 값. 60/10 = 6이라 1시간을 6으로 나눈 10분","","30분을 더한 값. 1시간을 2가 아니라 6으로 나눠야 함"],"t":"분수 식은 '1/24 = 1시간'에서 출발해 나머지 숫자로 나누세요. 1/24/(60/10) → 60분 ÷ 6 = 10분처럼 분 단위로 바꾸면 빠릅니다."},"1719":{"k":["단순 CASE: `CASE 컬럼 WHEN 값 THEN … ELSE … END` (= 비교만)","검색 CASE: `CASE WHEN 조건 THEN …`","DECODE(컬럼, 비교값, 결과, 기본값) 순서"],"w":["IS는 NULL 비교(IS NULL)에만 쓰는 연산자. `LOC IS 'NEW YORK'`은 문법 오류","","CASE의 기본값은 ELSE. DEFAULT라는 키워드는 없어서 오류","DECODE는 (컬럼, 비교값, 결과, 기본값) 순서. 'EAST'와 'NEW YORK' 자리가 바뀌어 LOC = 'EAST'일 때 'NEW YORK'을 돌려주는 식이 됨"],"t":"= 조건 하나만 쓰는 검색 CASE는 언제나 단순 CASE로 바꿀 수 있습니다. 바꿀 때 ELSE와 END가 그대로 있는지 확인하세요."},"1720":{"k":["조건부 집계: `SUM(CASE WHEN 조건 THEN 1 END)` → 맞는 행만 1, 나머지는 NULL이라 빠짐","ELSE 1을 붙이면 **모든 행이 1** → 전체 인원 수가 됨","ISNULL(SQL Server) = NVL(Oracle)"],"w":["SQL Server의 ISNULL로 NULL을 0으로 바꾼 것. 포지션별 인원이 정상으로 나옴","단순 CASE로 같은 조건을 쓴 것. 결과 같음","검색 CASE로 같은 조건. 결과 같음",""],"t":"CASE 집계 문제는 ELSE가 무엇인지부터 보세요. ELSE가 없거나 ELSE 0이면 정상, ELSE 1처럼 '맞지 않는 행에도 값'을 주면 결과가 달라집니다."},"1721":{"k":["HAVING은 **그룹 단위 조건**","`HAVING MAX(수량) > 10` = 그룹(고객) 안에 수량 10 초과 주문이 **한 번이라도** 있음","SELECT의 SUM(수량)은 그 고객 전체 주문의 합"],"w":["고객번호가 아니라 수량에 대한 조건","","주문 횟수를 세려면 COUNT(*) > 10이어야 함. MAX는 가장 큰 수량 값","합계 조건이면 HAVING SUM(수량) > 10이어야 함. 여기는 MAX"],"t":"HAVING 해석은 집계함수 이름을 그대로 읽으세요. MAX > 10 = '가장 큰 게 10 초과' = '하나라도 10 초과'."},"1722":{"k":["**NULLIF(A, B)**: A = B면 NULL, 다르면 A","NVL(A, B): A가 NULL이면 B / COALESCE: 첫 번째 NULL 아닌 값"],"w":["","NVL은 첫 인자가 NULL일 때 두 번째 값으로 바꾸는 함수. 같으면 NULL로 만드는 기능이 아님","IFNULL은 MySQL 함수이고 기능도 NVL과 같음","COALESCE는 나열된 값 중 처음으로 NULL이 아닌 값을 돌려줌"],"t":"'같으면 NULL'은 NULLIF뿐입니다. 이름에 IF가 붙어 '같으면(IF) NULL'로 외우세요."},"1723":{"k":["ORDER BY에는 **컬럼명 · 별칭 · 위치번호**를 쓸 수 있음","별칭을 붙여도 원래 컬럼명으로 정렬 가능","정렬 방향(ASC/DESC)이 결과를 가름"],"w":["DNAME ↑, LOC ↑, 세 번째 컬럼(DEPTNO) ↓. 기준 결과","AREA는 LOC의 별칭이라 ①과 같은 정렬","1번 = DNAME, AREA = LOC, 3번 = DEPTNO DESC. ①과 같음",""],"t":"정렬 비교 문제는 각 보기를 '컬럼 + 방향' 목록으로 바꿔 적어 보세요. 방향 하나가 다른 보기가 답입니다."},"1724":{"k":["LIKE: `_` = 정확히 1글자, `%` = 0글자 이상","'2번째 글자 S' → 앞에 `_` 하나 + S","'4글자 이상' → `_` 개수 + 최소 글자 수 확인"],"w":["","_ S % _ _ → 1글자 + S + 0글자 이상 + 2글자 = 2번째가 S, 최소 4글자. 조건 만족","_ S _ % _ → 2번째가 S, 최소 4글자. 조건 만족","_ S _ _ % → 2번째가 S, 최소 4글자. 조건 만족"],"t":"%는 '없어도 된다'는 점이 핵심입니다. 패턴 맨 앞에 %가 있으면 그 뒤 글자가 몇 번째인지 보장할 수 없어요."},"1725":{"k":["묶기 = **GROUP BY**, 그룹 조건 = HAVING","내림차순 = **DESC**, 오름차순(기본) = ASC"],"w":["","HAVING은 이미 묶인 그룹을 거르는 절. 그룹을 만드는 건 GROUP BY","ASC는 오름차순이라 '내림차순'과 반대","HAVING도 ASC도 모두 틀림"],"t":"'~별로 묶어' → GROUP BY, '~별 ~가 n 이상인' → HAVING. 문제 문장의 동사로 구분하세요."},"1726":{"k":["SUBSTR(문자, 시작, 길이): 위치는 **1부터**, **공백도 한 글자**","ROUND(4.875, 2) → 셋째 자리에서 반올림 = 4.88"],"w":["소수 셋째 자리 5에서 반올림해 4.88. 맞음","'KOREAN'은 6글자. 맞음","MySQL DATE_FORMAT으로 '%Y-%m-%d' 형식 출력 2022-11-02. 맞음",""],"t":"SUBSTR 문제는 글자 위에 번호를 직접 적으세요. G1 a2 n3 g4 n5 e6 u7 n8 처럼 세면 실수가 없습니다."},"1727":{"k":["**인라인 뷰**(FROM 절 서브쿼리)는 같은 FROM의 다른 테이블을 참조할 수 없음","'~별 최초' = GROUP BY ~ + MIN(날짜)를 인라인 뷰로 만든 뒤 원본과 조인"],"w":["인라인 뷰 안에서 바깥 FROM의 C를 참조함. 인라인 뷰는 상관 서브쿼리처럼 쓸 수 없어 오류","","광고ID로 묶으면 '광고별' 최초 일자가 나와 광고매체별 최초가 아님","GROUP BY가 없어 전체에서 최소값 한 건만 나옴. 광고매체별이 아님"],"t":"'~별'이라는 말이 나오면 GROUP BY 기준이 그 컬럼인지부터 확인하세요. 기준만 틀려도 보기 둘이 빠집니다."},"1728":{"k":["`ROLLBACK TO SAVEPOINT a` = a **이후** 작업만 취소, a 이전은 유지","COMMIT 전까지 살아 있는 작업이 모두 확정"],"w":["(나)·(다)는 SAVEPOINT a 이후라 ROLLBACK TO a로 취소됨","(나)·(다)는 취소됐고, (마)는 COMMIT 전에 실행돼 반영됨","(가)는 SAVEPOINT a 이전이라 살아 있음. (나)·(다)는 취소",""],"t":"SAVEPOINT 문제는 위에서부터 '살아 있는 작업 목록'을 적어 가며 따라가세요. ROLLBACK TO가 나오면 그 지점 아래를 지우면 됩니다."},"1729":{"k":["GROUP BY는 **NULL도 하나의 그룹**으로 묶음","MAX·MIN은 NULL 제외, 전부 NULL이면 NULL","COLA + COLC는 둘 중 하나라도 NULL이면 NULL → SUM에서 빠짐"],"w":["","COLB가 NULL인 그룹이 빠짐. 또 MIN(COLA)는 NULL을 빼고 계산하므로 NULL이 아니라 실제 최솟값","COLB NULL 그룹은 COLA가 NULL이라 COLA + COLC도 NULL → SUMAC는 NULL. 나 그룹도 3 + 0 = 3이라 5가 아님","COLB NULL 그룹이 빠졌고 MIN(COLA)도 NULL이 아님"],"t":"GROUP BY 결과 행 수를 셀 때 NULL 그룹을 잊지 마세요. 보기 행 수만 세도 답이 좁혀지는 문제가 많습니다."},"1730":{"k":["HAVING COUNT(*) = 2 → 정확히 2건인 ID만 (100, 999)","ORDER BY에 CASE를 쓰면 **바꾼 값**으로 정렬 → 999는 0이 되어 맨 앞"],"w":["999가 정렬용으로 0이 되므로 100보다 앞에 와야 함","","200은 3건이라 HAVING에서 빠짐","200이 들어갈 수 없고 순서도 틀림"],"t":"ORDER BY 안의 CASE는 화면에 보이는 값이 아니라 '정렬 키'만 바꿉니다. 결과에는 원래 값(999)이 그대로 나와요."},"1731":{"k":["GROUP BY가 있으면 SELECT·ORDER BY에는 **GROUP BY 컬럼, 집계함수, 별칭**만","GROUP BY가 없으면 SELECT에 없는 컬럼으로도 정렬 가능"],"w":["매출금액은 SELECT에서 SUM에 붙인 별칭이라 ORDER BY에서 쓸 수 있음","GROUP BY가 없어서 SELECT에 없는 '년' 컬럼으로도 정렬 가능","","COUNT(*)는 집계함수라 GROUP BY 쿼리의 ORDER BY에 올 수 있음"],"t":"GROUP BY 쿼리에서는 '그룹 하나에 값이 하나로 정해지나?'를 물어보세요. 지역별로 묶었는데 '년'은 여러 개라 정렬 기준이 될 수 없습니다."},"1732":{"k":["1/12 = **2시간** (하루 24시간 ÷ 12)","1/12/(60/30) = 2시간 ÷ 2 = **1시간**"],"w":["1/12(2시간)만 더한 값. (60/30) = 2로 한 번 더 나눠야 함","1시간 30분. 계산상 나올 수 없는 값","","30분. 2시간을 4로 나눈 값"],"t":"1/12, 1/24, 1/48 같은 분수는 '하루 24시간을 몇으로 나눴나'로 바꾸면 바로 시간이 나옵니다. 1/12 → 2시간, 1/48 → 30분."},"1733":{"k":["NULLIF(A, B): 같으면 **NULL**","COALESCE: 첫 NULL 아닌 값 / NVL(A, B): A가 NULL이면 B"],"w":["COALESCE(NULL, 'A')는 처음 나오는 NULL 아닌 값 'A'를 돌려줌","","NVL('A', NULL)은 첫 인자가 NULL이 아니라 그대로 'A'","NVL(NULL, 0)은 0, 0 + 10 = 10"],"t":"NULL 함수 결과 문제는 함수마다 '첫 인자가 NULL인가?'부터 확인하면 한 줄씩 금방 계산됩니다."},"1734":{"k":["실행 순서: **FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY**"],"w":["적는 순서일 뿐 실행 순서가 아님. SELECT는 거의 마지막","SELECT가 WHERE보다 먼저 실행되지 않음","ORDER BY는 SELECT 결과를 정렬하므로 SELECT 뒤에 와야 함",""],"t":"'프웨그해셀오'로 외우세요. 별칭·집계함수 위치 문제도 전부 이 순서로 풀립니다."},"1735":{"k":["테이블 N개 조인에 필요한 조건은 최소 **N − 1**개","조건이 빠지면 그 사이에 카티션 곱 발생"],"w":["2개면 테이블 3개만 이을 수 있음","3개면 테이블 4개만 이을 수 있음","","N − 1개면 충분. 5개는 최소가 아님"],"t":"테이블을 점, 조인 조건을 선이라고 생각하면 점 5개를 한 줄로 잇는 데 선 4개가 필요합니다."},"1736":{"k":["컬럼은 **실제로 있는 테이블**에서 가져와야 함","여러 테이블에 같은 이름 컬럼이 있으면 **테이블명(별칭) 필수**","출연 = 배우와 영화를 잇는 교차 테이블"],"w":["출연 테이블에는 영화명이, 영화 테이블에는 배우명이 없어 오류","영화번호 = 배우번호처럼 의미 없는 조인 조건. 결과가 틀림 (> 8888도 '이상' 조건과 다름)","영화번호·배우번호가 두 테이블에 동시에 있어 접두사 없이 쓰면 '열의 정의가 애매함' 오류",""],"t":"조인 보기 비교는 세 가지만 보세요. ① 컬럼이 그 테이블에 있나 ② 조인 조건이 PK-FK로 맞게 이어졌나 ③ 공통 컬럼에 접두사가 붙었나."},"1737":{"k":["조인은 일반적으로 **PK-FK** 관계로 성립","EQUI = '=' 조인, 그 외 비교 연산자는 NON EQUI","옵티마이저는 테이블이 몇 개든 **2개씩** 짝지어 조인"],"w":["(마) NON EQUI JOIN은 대부분 가능하지만 설계상 불가능할 때도 있다는 설명이 맞아서 포함돼야 함","(나)는 틀린 설명. 3개씩이 아니라 항상 2개씩 조인","(나)는 틀렸고 맞는 (마)가 빠짐",""],"t":"조인 처리 단위는 늘 '두 개씩'입니다. 3개, 여러 개를 한 번에 조인한다는 문장은 오답."},"1738":{"k":["LIKE도 조인 조건이 될 수 있음 → 조건을 만족하는 **모든 조합**이 결과","S% → S로 시작, %T% → T 포함"],"w":["조건에 맞는 조합이 있으므로 0건이 아님","규칙 하나(S%)만 계산한 값. %T%도 SMITH·SCOTT 두 건이 맞음","","3 × 2 = 6은 조건이 없는 CROSS JOIN 결과. ALLEN은 두 규칙 모두 안 맞음"],"t":"규칙 테이블 조인은 '사원 × 규칙' 표를 그려 O·X를 채우면 됩니다. 칸 6개 중 O 개수가 답."},"1739":{"k":["순수 관계 연산자: **SELECT · PROJECT · JOIN · DIVIDE**","일반 집합 연산자: UNION · INTERSECTION · DIFFERENCE · PRODUCT"],"w":["SELECT(σ)는 행을 고르는 순수 관계 연산자","","JOIN은 순수 관계 연산자","DIVIDE도 순수 관계 연산자 (SQL에 직접 대응하는 구문은 없음)"],"t":"관계대수 연산자 목록에 DML 명령(UPDATE, INSERT, DELETE)이 섞여 있으면 그게 답입니다. 관계대수는 '조회'만 다룹니다."},"1740":{"k":["'B에 있는 건 빼고' = **NOT EXISTS** (안티 조인)","NOT EXISTS 안에서는 빼야 할 대상과 **모든 키(고객ID + 컨텐츠ID)**를 맞춰야 함","LEFT JOIN으로 빼려면 `IS NULL`"],"w":["NOT EXISTS 안에 컨텐츠ID 조건이 없어서, 고객이 비선호를 하나라도 등록했으면 그 고객의 추천이 전부 빠짐","비선호컨텐츠 기준 RIGHT OUTER JOIN이라 비선호에 등록된 것 위주로 남음. 원하는 것과 반대","LEFT OUTER JOIN 후 `D.컨텐츠ID IS NOT NULL`이면 비선호로 등록된 컨텐츠만 남음. 제외하려면 IS NULL이어야 함",""],"t":"'제외하라'는 문제는 NOT EXISTS의 서브쿼리 WHERE에 바깥과 맞출 키가 전부 들어갔는지부터 확인하세요. 키 하나 빠지면 너무 많이 지워집니다."},"1741":{"k":["직접 연결하는 컬럼이 없는 두 테이블을 조인하면 **카티션 곱**","M:N은 교차 엔터티(생산제품)를 거쳐야 연결됨","필요한 정보가 어느 테이블에 있는지 보고 조인 수를 최소로"],"w":["생산제품은 제품과 한 번, 생산라인과 한 번 조인되니 WHERE에 최소 2번 나오면 됨","","생산제품 쪽 끝이 ○(선택)라 생산제품과 대응되지 않는 제품·생산라인이 있을 수 있음","라인번호는 생산제품에도 있으므로 제품 + 생산제품 두 개만 조인하면 제품명을 알 수 있음"],"t":"'몇 개 조인해야 하나'는 '찾는 컬럼'과 '조건 컬럼'이 각각 어느 테이블에 있는지만 표시하면 바로 보입니다."},"1742":{"k":["'구매 이력이 있는 고객만' → **INNER JOIN**","'구매 횟수' → **COUNT**, 그룹 조건 → **HAVING**"],"w":["SUM(구매번호)는 구매번호 값을 더한 것이지 횟수가 아님","","LEFT OUTER JOIN이면 구매 이력이 없는 고객도 붙고, SUM으로 횟수를 셀 수도 없음","WHERE는 GROUP BY 앞에 와야 하고 그룹 조건(횟수)을 걸 수 없음. '구매번호 >= 3'은 횟수와 무관"],"t":"'횟수·건수'는 COUNT, '금액·합계'는 SUM. 문제 문장의 명사로 집계함수를 고르세요."},"1743":{"k":["**NON EQUI 조인**: = 대신 범위 조건으로 짝 찾기","`B.사용시간대 BETWEEN C.시작시간대 AND C.종료시간대`","ANSI JOIN은 JOIN마다 ON이 하나씩"],"w":["부등호 방향이 반대. 사용시간대가 시작시간대 이상, 종료시간대 이하여야 함","INNER JOIN을 ON 없이 연달아 쓰고 ON 하나에 조건을 몰면 문법 오류","","'BETWEEN JOIN'이라는 구문은 없음"],"t":"급여 등급, 시간대 단가처럼 '구간 테이블'이 나오면 BETWEEN 조인입니다. BETWEEN 양쪽에 어느 컬럼이 오는지만 확인하세요."},"1744":{"k":["**USING (컬럼명)**: 이름만, 괄호 필수, **접두사·조건식 불가**","USING 컬럼은 SELECT에서도 접두사 없이 씀","ON, WHERE 방식은 접두사 필수"],"w":["","ANSI INNER JOIN ... ON으로 같은 조건. 정상","Oracle 방식 WHERE 등가 조인. 정상","테이블명을 그대로 접두사로 쓴 WHERE 조인. 정상"],"t":"USING과 NATURAL JOIN에는 '테이블명.컬럼'이 절대 붙지 않습니다. 점(.)이 보이면 오류 보기."},"1745":{"k":["조인 조건 없는 `FROM A, B` = **CROSS JOIN** (카티션 곱)","EMP 14 × DEPT 4 = 56행"],"w":["FULL OUTER JOIN은 ON 조건이 반드시 필요하고 결과도 다름","SELF JOIN은 같은 테이블을 두 번 쓰는 조인","NATURAL JOIN은 같은 이름 컬럼(DEPTNO)으로 등가 조인해 14행",""],"t":"조인 조건이 없는 쉼표 조인을 ANSI로 바꾸면 언제나 CROSS JOIN입니다."},"1746":{"k":["LEFT OUTER JOIN의 **ON 조건은 '붙일지'만** 정함 → 기준(왼쪽) 행은 전부 남음","기준 테이블 조건을 거르려면 WHERE에","고객번호 IN 조건이 ON에 있으니 6명 모두 출력"],"w":["","IN 조건을 WHERE에 둔 경우의 결과. ON에 있으면 고객 6명이 모두 남음","INNER JOIN처럼 짝 있는 행만 남긴 결과","ON의 IN 조건을 무시하고 모든 고객에게 단말기를 붙인 결과"],"t":"OUTER JOIN에서 기준 테이블 조건이 ON에 있으면 '걸러지지 않는다'가 핵심입니다. 행 수는 기준 테이블 그대로, 붙는 값만 줄어요."},"1747":{"k":["FULL OUTER = LEFT 결과 **∪** RIGHT 결과 (UNION으로 중복 제거)","= INNER + 왼쪽에만 있는 행 + 오른쪽에만 있는 행 (UNION ALL)"],"w":["(다)도 INNER + A만 있는 것 + B만 있는 것이라 FULL OUTER와 같음","(나)도 LEFT ∪ RIGHT라 FULL OUTER와 같음","(가)는 FULL OUTER 자체라 당연히 같음",""],"t":"FULL OUTER를 다른 방식으로 쓴 보기는 '양쪽 짝 있는 것, 왼쪽만, 오른쪽만' 세 부분이 모두 들어 있는지만 확인하면 됩니다."},"1748":{"k":["LEFT = 왼쪽 전부, RIGHT = 오른쪽 전부, FULL = 양쪽 전부","건수 = 매칭 행 + 기준 쪽 단독 행","매칭: EMP의 C = 'w' 2행 ↔ DEPT 'w' 1행 → 2행"],"w":["","LEFT는 EMP 3행이 기준. 4건이 될 수 없음","FULL은 매칭 2 + EMP 단독 1(y) + DEPT 단독 2(z, v) = 5건","RIGHT는 매칭 2 + DEPT 단독 2 = 4건. FULL은 5건"],"t":"외부 조인 건수 문제는 '매칭 수 / 왼쪽만 / 오른쪽만' 세 숫자를 먼저 구하세요. LEFT = 매칭 + 왼쪽만, RIGHT = 매칭 + 오른쪽만, FULL = 셋 다."},"1749":{"k":["'~이 없는 …도 출력' → 그 …가 **기준(보존) 테이블**","DEPT를 왼쪽에 두었으니 **LEFT** OUTER JOIN"],"w":["","RIGHT면 EMP가 기준이라 사원 없는 부서가 빠짐","FULL이면 부서가 없는 사원까지 나와 요구보다 많음","INNER면 짝이 없는 부서가 빠짐"],"t":"LEFT/RIGHT는 '살려야 하는 테이블이 JOIN 키워드의 왼쪽인가 오른쪽인가'로만 고르면 됩니다."},"1750":{"k":["LEFT JOIN의 ON에 오른쪽 조건(B.C2 BETWEEN 1 AND 3)을 두면 그 조건에 맞는 행만 **붙임**","왼쪽 TAB1 5행은 전부 남음"],"w":["D는 B.C2 = 4라 조건에 안 맞아 붙지 않고 NULL이어야 함","","ON 조건을 WHERE처럼 적용해 왼쪽 행까지 줄인 결과. LEFT JOIN은 왼쪽 행을 줄이지 않음","D에 TAB2가 붙었고 E도 빠짐. 둘 다 틀림"],"t":"LEFT JOIN 결과 행 수는 (짝이 여러 개가 아니라면) 왼쪽 테이블 행 수와 같습니다. 행 수부터 맞는 보기를 고르세요."},"1751":{"k":["(+)가 붙은 쪽 = NULL이 채워질 **Inner 쪽** (게시글)","Inner 쪽 조건(B.삭제여부(+) = 'N') → ANSI **ON** 절","Outer(기준) 쪽 조건(A.사용여부 = 'Y') → **WHERE** 절"],"w":["","기준(게시판) 조건을 ON에 넣으면 걸러지지 않아 사용여부 N인 게시판도 나옴","Inner 쪽 조건을 WHERE에 두면 게시글 없는 게시판(NULL 행)이 탈락 → INNER JOIN과 같아짐","RIGHT OUTER로 바꾸면 기준이 게시글이 되어 의미가 달라짐"],"t":"(+) → ANSI 변환은 '(+) 붙은 조건은 ON, 안 붙은 조건은 WHERE'로 기계적으로 옮기면 됩니다."},"1752":{"k":["**컬럼끼리 더하기**: NULL이 하나라도 있으면 그 행은 NULL","**SUM**: NULL 행은 빼고 더함","SUM(A + B) ≠ SUM(A) + SUM(B) (NULL이 있을 때)"],"w":["SUM(COL2)는 NULL을 빼고 20 + 70 = 90. NULL이 아님","앞 두 행은 NULL이 섞여 행 결과가 NULL → 세 번째 행 50 + 70 + 20 = 140만 남음","","SUM(COL2) = 90, SUM(COL3) = 20 → 110"],"t":"SUM(식) 문제는 '행마다 식을 먼저 계산 → NULL 행 버림 → 남은 것 합계' 순서로 표를 그려 푸세요."},"1753":{"k":["반환 형태로 나눈 서브쿼리: **단일 행 · 다중 행 · 다중 컬럼**","다중 컬럼: `(A, B) IN (SELECT A, B …)` — 개수·위치 일치, SQL Server 미지원"],"w":["단일 행 서브쿼리는 결과가 1건 이하인 것. 컬럼 수 이야기가 아님","","다중 행 서브쿼리는 결과 '행'이 여러 건인 것. 지문은 여러 '컬럼'","'단일 칼럼 서브쿼리'라는 분류는 따로 없음"],"t":"'여러 칼럼', '동시에 비교', '개수와 위치 동일' 세 표현이 나오면 다중 컬럼 서브쿼리입니다."},"1754":{"k":["ROLLUP(A) = A별 + **총계**","CUBE(A) = A별 + **총계** (인자 하나면 ROLLUP과 같음)","GROUPING SETS(A) = A별 **만** (총계 없음)"],"w":["COL1별 합계 + UNION ALL로 붙인 전체 합계. ROLLUP(COL1)과 같은 결과","","ROLLUP(COL1)은 COL1별 + 총계. ①과 같음","CUBE(COL1)도 인자가 하나라 COL1별 + 총계. ①과 같음"],"t":"GROUPING SETS는 괄호 안에 쓴 것만 나옵니다. 총계를 원하면 ()를 직접 넣어야 한다는 점이 ROLLUP·CUBE와 가장 큰 차이."},"1755":{"k":["UNION 합집합 · **INTERSECT 교집합** · MINUS(EXCEPT) 차집합"],"w":["UNION은 합집합","","MINUS는 Oracle의 차집합","EXCEPT는 SQL Server(표준)의 차집합"],"t":"INTERSECT = intersection(교차) = 교집합. 영어 뜻 그대로입니다."},"1756":{"k":["집합 연산의 **ORDER BY는 맨 끝에 한 번만**","각 SELECT에 WHERE·GROUP BY·HAVING은 사용 가능","UNION은 중복 제거, UNION ALL은 유지"],"w":["UNION은 합친 뒤 중복 행을 하나로 만듦. 맞음","애초에 겹치는 행이 없으면 중복 제거할 게 없어 UNION과 UNION ALL 결과가 같음. 맞음","각 SELECT 문 안에 GROUP BY를 쓰는 건 가능. 맞음",""],"t":"ORDER BY는 '최종 결과'를 정렬하는 절이라 집합 연산 전체에 한 번뿐입니다. 중간 SELECT에 ORDER BY가 보이면 오류."},"1757":{"k":["INTERSECT(전체 ∩ 이용) = 이용된 적 있는 서비스","같은 결과: `NOT EXISTS (전체 MINUS 이용)` = 이용 안 된 것이 아닌 것","1:N 조인은 N쪽 건수만큼 중복이 생김"],"w":["서비스와 서비스이용은 1:N이라 그냥 조인하면 이용 건수만큼 같은 서비스가 반복 출력됨. INTERSECT는 중복 없음","","LEFT JOIN 후 IS NULL이면 이용된 적 없는 서비스만 나와 반대 결과","MINUS 순서가 반대(이용 − 전체)라 서비스에 없는 서비스ID를 찾는 셈. 사실상 0건"],"t":"집합 연산을 EXISTS·조인으로 바꾼 보기는 '중복 행이 생기는가'와 '방향(A−B인지 B−A인지)'만 확인하세요."},"1758":{"k":["집합 연산자는 **위에서부터 차례로** 수행 (괄호 없으면 우선순위 없음)","마지막이 UNION이면 그때까지 쌓인 결과 전체에서 중복 제거"],"w":["","(TBL1 UNION ALL TBL2)까지만 계산하고 마지막 UNION의 중복 제거를 빠뜨린 결과","UNION ALL만 세 번 한 결과. 마지막 UNION이 중복을 모두 없앰","계산상 나올 수 없는 결과"],"t":"UNION ALL과 UNION이 섞이면 '마지막 연산자'가 결과를 결정하는 경우가 많습니다. 마지막이 UNION이면 결과에 중복이 하나도 없어요."},"1759":{"k":["ROLLUP(A, B) = (A,B) + (A) + **()**","A, ROLLUP(B) = (A,B) + (A) — **총계 없음**","A, CUBE(B) = (A,B) + (A) (B 하나라 ROLLUP과 같음)","GROUPING SETS(A, (B, A)) = (A) + (A,B)"],"w":["GROUPING SETS(grade, (job, grade))는 grade별 + (grade, job)별. 결과표와 같음","","grade를 바깥에 두면 모든 그룹에 grade가 들어가 (grade, job) + (grade)만 생김. 결과표와 같음","CUBE(job)도 인자가 하나라 (grade, job) + (grade). 결과표와 같음"],"t":"결과표 맨 아래에 전체 총계 행(GRADE·JOB 모두 NULL)이 있는지부터 보세요. 없는데 ROLLUP(전체)가 보기에 있으면 그게 다른 결과입니다."},"1760":{"k":["`SUM(…) OVER (PARTITION BY 부서)` = 부서 **전체** 합","`OVER (PARTITION BY 부서 ORDER BY …)` = **누적** 합 (기본 RANGE ~ CURRENT ROW)","RATIO_TO_REPORT = 파티션 합 대비 비율"],"w":["RATIO_TO_REPORT(급여) OVER (PARTITION BY 부서코드)는 부서 합 대비 비율이라 결과와 같음","급여 ÷ 부서 전체 합(PARTITION BY만 사용)이라 결과와 같음","부서별 합계를 인라인 뷰로 구해 조인한 방식. 결과와 같음",""],"t":"윈도우 함수에 ORDER BY가 붙는 순간 '전체'가 '누적'으로 바뀝니다. 비율·합계 문제에서 OVER 안에 ORDER BY가 있는 보기를 먼저 의심하세요."},"1761":{"k":["1:1 양쪽 필수 → 두 테이블의 회원ID **집합이 똑같음**","같은 집합이면: INTERSECT = UNION = 원래 집합, EXCEPT = 공집합","UNION ALL = 두 배"],"w":["두 집합이 같아서 EXCEPT 결과는 항상 0건. 상세정보 없는 회원은 존재할 수 없음","UNION ALL은 중복을 남기므로 회원기본정보 건수의 2배","","같은 집합끼리는 INTERSECT 결과와 UNION 결과가 같음"],"t":"'1:1 양쪽 필수'라는 단서는 '두 키 집합이 같다'는 뜻입니다. 이 한 줄로 집합 연산 결과를 전부 계산할 수 있어요."},"1762":{"k":["START WITH = 루트, CONNECT BY PRIOR 부모키 = 자식FK → 순방향","**ORDER SIBLINGS BY**: 트리 모양 유지, 같은 부모 아래 형제끼리만 정렬","깊이 우선: 자식을 끝까지 내려간 뒤 다음 형제"],"w":["A는 루트라 1번째","","C는 형제 중 DESC로 먼저 와서 2번째","D는 B의 자식이라 B 다음, 4번째"],"t":"계층 출력 순서는 손으로 트리를 그린 뒤 '왼쪽 가지부터 끝까지' 내려가며 번호를 붙이면 정확합니다."},"1763":{"k":["루트 노드 **LEVEL = 1** (0 아님)","START WITH 시작점 / ORDER SIBLINGS BY 형제 정렬 / 순방향 = 부모 → 자식"],"w":["START WITH로 계층 시작점(루트)을 지정. 맞음","ORDER SIBLINGS BY는 형제 노드끼리만 정렬. 맞음","부모에서 자식 방향으로 내려가는 것이 순방향 전개. 맞음",""],"t":"LEVEL, ROWNUM, SUBSTR 위치처럼 Oracle의 순번은 모두 1부터 시작합니다. 0이 나오면 의심하세요."},"1764":{"k":["START WITH로 고른 **루트는 조건과 상관없이 포함**","CONNECT BY의 추가 조건은 **자식을 펼칠 때만** 적용 → 안 맞으면 그 가지째 제외","WHERE 조건은 전개 후 그 행만 제외"],"w":["","루트 001(2012년 입사)이 빠짐. 루트는 CONNECT BY 조건과 무관하게 나옴","루트 005와 001의 자식 003, 004가 빠짐","입사일자 조건을 무시하거나 엉뚱한 쪽에 적용한 결과. 006~008은 2014년 입사라 붙을 수 없음"],"t":"계층형 문제에서 조건이 CONNECT BY에 있는지 WHERE에 있는지가 답을 가릅니다. CONNECT BY면 '가지치기', WHERE면 '그 줄만 지우기'."},"1765":{"k":["PRIOR는 **CONNECT BY, SELECT, WHERE** 절에서 사용 가능","'PRIOR 자식 = 부모' → 순방향","SQL Server는 재귀 CTE(앵커 멤버 → 재귀 멤버)로 계층 전개"],"w":["SQL Server는 CTE를 재귀 호출해 계층을 펼침. 맞음","앵커 멤버로 시작 집합을 만들고 재귀 멤버를 반복 실행. 맞음","Oracle 계층 질의의 WHERE는 전개가 끝난 뒤 필터로 동작. 맞음",""],"t":"'~에만 사용할 수 있다'처럼 범위를 한정하는 문장은 거의 오답입니다. 문장 뒷부분이 맞아도 앞부분 한정어를 보세요."},"1766":{"k":["위로(역방향) + 아래로(순방향)를 모두 보려면 두 계층 질의를 **UNION**","역방향: `CONNECT BY PRIOR 상위코드 = 코드` / 순방향: `CONNECT BY 상위코드 = PRIOR 코드`","LEVEL은 각 질의의 시작점 기준"],"w":["","100부터 순방향이라 아시아지부 아래 모든 지사·지점이 LVL 1~3으로 나옴","121부터 역방향이라 121, 120, 100만 나오고 122가 빠짐","최상위(100)를 찾아 다시 순방향으로 펼쳐 ②와 같은 결과"],"t":"결과표의 LVL 값이 단서입니다. 시작점(120)이 LVL 1이고 위아래가 모두 LVL 2면 '시작점에서 양방향'이라는 뜻이에요."},"1767":{"k":["INNER JOIN ON · USING · NATURAL JOIN은 같은 조건이면 같은 결과","**CROSS JOIN** = 모든 조합 (1 × 2 = 2건)"],"w":["INNER JOIN ON B.NO = A.NO. 원래 SQL과 같은 1건","USING(NO)로 같은 등가 조인. 1건","","NATURAL JOIN은 같은 이름 컬럼 NO로 조인. 1건"],"t":"조인 문법 변환 문제는 '조인 조건이 그대로 살아 있나'만 보면 됩니다. 조건이 사라진 CROSS JOIN이 보통 답."},"1768":{"k":["윈도우 함수 없이 누적 합: **셀프 조인** + `A.일자 >= B.일자` + A.일자로 GROUP BY + SUM(B.값)","A = 기준일, B = 기준일까지의 모든 날"],"w":["셀프 조인 없이 일자별로 묶으면 그날 매출만 나와 전부 1000","B.일자로 묶으면 각 날짜 '이후' 날짜들이 붙어 역순 누적(첫날 10000)이 됨","","B.일자 >= A.일자라 그날부터 끝날까지 합 = 남은 기간 합계(역순 누적)"],"t":"누적 셀프 조인은 '기준 쪽으로 묶고, 반대쪽 값을 더한다'입니다. 부등호 방향과 GROUP BY 쪽이 일치하는지 확인하세요."},"1769":{"k":["단일 행 서브쿼리 결과로 비교 (E = 'i' → D = 'x')","COUNT(DISTINCT 식) = 식 결과의 **종류 수**","|| = 문자 연결"],"w":["D = 'x'인 행이 두 개 있어 0건이 아님","B 값('a')만 보고 중복을 센 결과. A||B는 '1a', '2a'로 서로 다름","","EMP 전체 3건을 센 결과. WHERE 조건으로 D = 'y'인 행은 빠짐"],"t":"DISTINCT 뒤가 '연결된 식'이면 연결한 결과 문자열을 실제로 적어 보고 서로 다른 개수를 세세요."},"1770":{"k":["다중 행 결과에는 **IN · ANY · ALL · EXISTS**","서브쿼리 위치: SELECT · FROM · WHERE · HAVING · ORDER BY 등","연관 서브쿼리 = 메인쿼리 컬럼을 참조","다중 컬럼 서브쿼리는 **SQL Server 미지원**"],"w":["(마)는 SQL Server에서 다중 컬럼 비교를 지원하지 않아 틀림","","(다) 여러 행 결과를 =, <= 같은 단일 행 연산자로 비교하면 오류","(마)가 틀렸고, 맞는 (라)가 빠짐"],"t":"'오라클 및 SQL Server 등 모두'처럼 여러 DBMS를 한꺼번에 묶는 문장은 차이점 함정인 경우가 많습니다."},"1771":{"k":["**RATIO_TO_REPORT** = 값 / 파티션 합 (A그룹 합 100 → 10/100 = 0.1)","**NTILE(5)** = 정렬 후 5등분 번호 (10행 → 2개씩 1~5)","PERCENT_RANK는 0부터, RANK·DENSE_RANK는 1~n"],"w":["PERCENT_RANK는 첫 행이 0이라 0.1이 나올 수 없고, DENSE_RANK(VAL2)는 1~10이 나옴","CUME_DIST는 누적 비율이라 0.1, 0.2 패턴이 안 나오고, RANK도 1~10","PERCENT_RANK는 0부터 시작하고 RANK는 1~10",""],"t":"결과 숫자 패턴을 먼저 읽으세요. 1,1,2,2,3,3… 처럼 같은 숫자가 일정하게 반복되면 NTILE, 합이 1이 되는 비율이면 RATIO_TO_REPORT."},"1772":{"k":["'N이 하나라도 있는 회원' = EXISTS / IN / 조인 + GROUP BY 모두 가능","EXISTS·스칼라 서브쿼리에 **바깥과 연결하는 조건**이 빠지면 전체 테이블 기준으로 판단"],"w":["EXISTS + 회원번호 연관 조건으로 'N이 있는 회원'만 남김. 같은 결과","IN 서브쿼리로 'N이 있는 회원번호' 목록과 비교. 같은 결과","","조인 후 'N'인 행만 남기고 GROUP BY로 중복을 없앰. 같은 결과"],"t":"서브쿼리 보기 중 바깥 테이블 별칭(A.)이 서브쿼리 안에 하나도 안 나오는 보기를 찾으세요. 연관 조건이 빠진 그 보기가 대개 다른 결과입니다."},"1773":{"k":["EXISTS 안의 **HAVING**: GROUP BY가 없으면 서브쿼리 결과 전체가 한 그룹","`COUNT(*) < 전체 이벤트 수` = 회원별 받은 메일이 이벤트 수보다 적음 = **발송 누락 회원**","㉡ 연관 조건으로 회원마다 따로 셈"],"w":["모든 회원이 아니라 받은 메일 수가 이벤트 수보다 적은, 즉 발송이 누락된 회원만 뽑음","㉡을 빼면 회원별로 셀 수 없고 전체 발송 건수로 비교하게 되어 결과가 달라짐","","GROUP BY 없이 HAVING만 써도 결과 전체를 한 그룹으로 보고 정상 실행됨"],"t":"EXISTS 안에 HAVING이 보이면 '조건을 만족하는 그룹이 있나'로 읽으세요. 서브쿼리가 0행이면 거짓, 1행이면 참입니다."},"1774":{"k":["다중 행 연산자(IN, ANY, ALL, EXISTS)는 **단일 행 결과에도 사용 가능**","단일 행 연산자(=, <, >)는 다중 행 결과에 **사용 불가**","값을 넘겨주는 용도는 주로 비연관 서브쿼리"],"w":["단일 행 서브쿼리는 =, >, < 같은 단일 행 연산자를 씀. IN, ALL은 다중 행 연산자","","메인쿼리에 값을 제공하는 건 주로 비연관 서브쿼리. 연관 서브쿼리는 메인 행마다 조건 확인용","비연관 서브쿼리는 먼저 한 번 실행해 결과를 넘기기도 해서 '항상' 메인 먼저가 아님"],"t":"큰 그릇(다중 행 연산자)에는 작은 것(1행)도 담기지만, 작은 그릇(단일 행 연산자)에 큰 것(여러 행)은 안 담긴다고 생각하세요."},"1775":{"k":["FROM 절 서브쿼리 = **인라인 뷰(동적 뷰)**","SELECT 절 서브쿼리 = **스칼라 서브쿼리** (조인으로 바꿀 수 있음)","EXISTS는 '있느냐'만 확인 → 이미 걸러진 결과에 조건을 반복할 필요 없음"],"w":["EXISTS 안은 다중 행 연관, SELECT 절은 단일 행 연관, FROM 절은 인라인 뷰. 셋 다 쓰였음","스칼라 서브쿼리는 결과가 같도록 OUTER JOIN 등으로 바꿀 수 있음. 맞음","","인라인 뷰는 동적 뷰라고도 하며 테이블이 올 수 있는 자리에 씀. 맞음"],"t":"'조건을 추가해야 원하는 결과가 나온다'는 보기는 실제로 조건을 넣었을 때와 뺐을 때 결과가 달라지는지 확인해 보세요. 대개 차이가 없습니다."},"1776":{"k":["'항목별 **최종** 회차의 결과' = 연관 서브쿼리로 그 항목의 MAX(회차)를 구해 같은 행을 선택","컬럼별로 MAX를 따로 구하면 **서로 다른 행의 값**이 섞임"],"w":["평가결과 전체의 최대 회차 하나만 기준이라, 상품·항목마다 다른 최종 회차를 반영하지 못함","","회차·등급·일자를 각각 MAX로 구해 '마지막 회차의 등급'이 아니라 '가장 큰 등급'이 나올 수 있음","③과 같은 문제. 컬럼마다 MAX를 따로 구해 한 행의 값이 아님"],"t":"'최신 행 통째로'를 가져올 땐 MAX를 컬럼마다 쓰면 안 됩니다. MAX로 키를 찾은 뒤 그 키로 행을 다시 찾으세요."},"1777":{"k":["뷰: **정의만 저장**, 실행 시 재작성","장점: **독립성**(테이블이 바뀌어도 뷰만 수정) · 편리성 · 보안성","Materialized View처럼 데이터를 저장하는 뷰를 지원하는 DBMS도 있음"],"w":["뷰는 SQL 정의만 저장하고 실행할 때 원래 테이블에 대한 질의로 바꿔 수행. 맞음","","민감한 컬럼을 빼고 보여 주는 식으로 보안에 활용. 맞음","Oracle의 Materialized View처럼 실제 데이터를 저장하는 뷰도 있음. 맞음"],"t":"뷰의 장점 세 가지(독립성·편리성·보안성)를 거꾸로 서술한 보기를 찾으세요. '응용 프로그램을 바꿔야 한다'는 독립성을 뒤집은 문장입니다."},"1778":{"k":["뷰를 조회하면 **뷰 조건 AND 조회 조건**이 함께 적용","C1 = 'B' OR C1 IS NULL, 그리고 C2 >= 200 AND C1 = 'B' → ('B', 200) 한 행"],"w":["두 조건을 모두 만족하는 행이 있음","","C2 >= 200 조건을 빼고 'B' 행을 더한 값","C1 조건을 무시하고 C2 >= 200인 행을 모두 더한 값"],"t":"뷰 문제는 뷰 정의 조건과 바깥 조건을 AND로 이어 붙인 쿼리 하나로 생각하면 됩니다."},"1779":{"k":["ROW_NUMBER로 부서별 연봉 2등만 선택","SUM … ORDER BY 사원ID ROWS ~ CURRENT ROW = 부서별 **누적합**","ROWS CURRENT ROW = **자기 행만** → MAX도 자기 값"],"w":["COL3를 전체 최댓값(4500)으로 계산한 결과. ROWS CURRENT ROW라 자기 행만 봄","","COL2를 부서 전체 합으로 본 결과. ORDER BY 사원ID가 있어 누적합","COL2를 부서 전체 합으로 본 결과"],"t":"윈도우 문제는 OVER 안을 따로 해석하세요. ORDER BY가 있으면 누적, 범위가 CURRENT ROW뿐이면 자기 자신입니다."},"1780":{"k":["계층 소계(지역 → 월 → 전체) = **ROLLUP**","GROUPING(컬럼) = 소계로 생긴 NULL이면 **1**","지역ID로 묶었으면 지역명은 MIN(지역명)으로"],"w":["GROUPING = 0일 때 '지역전체'를 붙여 일반 행에 라벨이 잘못 붙음","","CUBE는 월별 전체 소계(지역 NULL, 월 있음)까지 만들어 행이 더 많음","GROUPING SETS는 지역별·월별 합계를 따로 만들 뿐 (지역, 월) 상세 행과 총계가 없음"],"t":"결과표에 소계가 '지역 안에서 월'로 계층적으로만 붙어 있으면 ROLLUP, 양쪽 방향으로 다 있으면 CUBE입니다."},"1781":{"k":["`>=` 같은 **단일 행 연산자**에 여러 행 서브쿼리 → ORA-01427 오류","'모두보다' = **ALL**, '하나라도' = **ANY**"],"w":["","서브쿼리가 부서별 MAX를 여러 행 돌려줘 실행 자체가 오류","'전부와 크거나 같은'은 >= ALL이어야 함. ANY로 쓰면 '하나라도'","'하나보다 크거나 같은'은 >= ANY여야 함. ALL로 쓰면 '전부'"],"t":"GROUP BY가 있는 서브쿼리는 거의 항상 여러 행을 돌려줍니다. 앞의 연산자가 단일 행용이면 바로 오류."},"1782":{"k":["ROLLUP(A, B) = (A,B) + A 소계 + **총계**","CUBE는 B 소계도 추가, GROUPING SETS·A, ROLLUP(B)는 총계 없음"],"w":["","CUBE면 JOB별 소계(DNAME이 NULL인 행)까지 나옴","GROUPING SETS((DNAME, JOB), DNAME)에는 전체 합계 행이 없음","DNAME, ROLLUP(JOB)은 DNAME이 항상 있어 전체 합계 행이 없음"],"t":"결과 맨 마지막 줄 (NULL, NULL, 총계)이 있으면 ROLLUP 또는 CUBE, 없으면 둘 다 아닙니다. 그다음 중간 소계 방향을 보세요."},"1783":{"k":["CUBE(A, B) = (A,B) + A 소계 + B 소계 + 총계 (**모든 조합**)","같은 그룹을 중복 지정하면 같은 행이 여러 번 나옴"],"w":["CUBE 안에서 (설비ID, 에너지코드) 조합을 또 넣어 같은 그룹이 중복 생성됨","","설비ID별 소계만 있고 에너지코드별 소계와 총계가 빠짐","총계(()) 행이 빠짐"],"t":"결과표에 '앞 컬럼 NULL'인 소계와 '뒤 컬럼 NULL'인 소계가 둘 다 있고 총계도 있으면 CUBE입니다."},"1784":{"k":["ROLLUP((A, B)): 괄호로 묶은 (A, B)를 **한 단위**로 → (A,B) + 총계만","ROLLUP(A, B)·ROLLUP((A),(B)) = (A,B) + A + 총계"],"w":["JOB별 소계 행까지 생김","","ROLLUP((JOB),(DEPTNO))는 ROLLUP(JOB, DEPTNO)와 같아 JOB 소계가 생김","JOB별 소계가 생기고 총계는 없음"],"t":"ROLLUP 안의 괄호는 '이건 쪼개지 마'라는 뜻입니다. 괄호 덩어리 개수 + 1이 그룹 수준 개수예요."},"1785":{"k":["GROUPING SETS((A, B)) = 그룹 하나만 지정 = **GROUP BY A, B**와 같음","소계·총계 없음"],"w":["GROUPING SETS(월, 상품ID)처럼 각각 따로 묶은 결과","","GROUPING SETS(월, 상품ID, ())처럼 총계까지 넣은 결과","GROUPING SETS((월, 상품ID), 월)처럼 월 소계를 넣은 결과"],"t":"GROUPING SETS 안의 괄호 개수를 세세요. 바깥 괄호 안에 묶음이 하나뿐이면 그냥 일반 GROUP BY입니다."},"1786":{"k":["윈도우 함수는 **행 수를 줄이지 않음** (행마다 값을 붙임)","PARTITION BY ≈ GROUP BY처럼 나누지만 결과는 그대로","적용 범위는 파티션 안"],"w":["데이터를 나눈다는 점에서 PARTITION BY와 GROUP BY는 의미상 비슷. 맞음","PARTITION BY가 없으면 전체가 하나의 파티션. 맞음","","윈도우 범위는 파티션 경계를 넘지 않음. 맞음"],"t":"'건수가 줄어든다'는 GROUP BY 이야기입니다. 윈도우 함수 설명에 나오면 오답."},"1787":{"k":["**RANK**: 동점 같은 순위, 다음 순위 건너뜀 (1, 1, 3)","DENSE_RANK는 안 건너뜀, ROW_NUMBER는 동점 없음"],"w":["","ROW_NUMBER 결과. 동점에도 다른 번호를 줌","DENSE_RANK 결과. 동점 뒤 순위를 건너뛰지 않음","오름차순으로 매긴 결과. DESC라 큰 값이 1위"],"t":"순위 함수 구분은 동점 다음 숫자만 보면 됩니다. 1,1,3 RANK / 1,1,2 DENSE_RANK / 1,2,3 ROW_NUMBER."},"1788":{"k":["결과 순위가 1, 2, 2, **3** → 동점 뒤에도 이어짐 = **DENSE_RANK**"],"w":["ROWNUM은 윈도우 함수가 아니라 OVER와 함께 쓸 수 없음","ROW_NUMBER면 FORD와 SCOTT가 2, 3처럼 서로 다른 번호","RANK면 공동 2위 다음이 4위가 됨",""],"t":"결과표에서 동점 바로 다음 행의 순위 숫자 하나만 확인하세요."},"1789":{"k":["`ROW_NUMBER() OVER (PARTITION BY 그룹 ORDER BY 값 DESC)` + `RNUM = 1` = **그룹별 최고 1건**","윈도우 함수는 인라인 뷰로 감싼 뒤 WHERE로 거름"],"w":["필터를 적용하지 않은 전체 결과","파티션 없이 전체 1등만 뽑은 결과","","ORDER BY를 오름차순으로 본 결과(그룹별 최저)"],"t":"그룹별 Top-1 패턴은 시험에 아주 자주 나옵니다. PARTITION BY가 '그룹', ORDER BY 방향이 '최고/최저'를 정합니다."},"1790":{"k":["GROUP BY 결과 위에 윈도우 함수 사용 **가능** (윈도우는 GROUP BY 뒤에 계산)","윈도우 ORDER BY에 집계함수 사용 가능","RANGE ±10000 = 값 기준 범위 안의 **행(그룹) 개수**"],"w":["GROUP BY와 윈도우 함수는 함께 쓸 수 있음. 윈도우 함수는 그룹화된 결과에 적용","윈도우 ORDER BY에 AVG 같은 집계함수를 쓸 수 있음","","비교 대상은 개별 상품이 아니라 GROUP BY로 만든 상품분류코드별 평균 행"],"t":"윈도우 함수가 GROUP BY와 같이 있으면 '묶인 결과 행' 위에서 계산된다고 보세요. 세는 대상도 묶인 행입니다."},"1791":{"k":["`MAX(…) OVER (PARTITION BY 부서)` = 행마다 **부서 최고값**을 붙임","연봉 = 부서 최고연봉인 행만 남기면 부서별 최고 연봉자"],"w":["","부서별 최저 연봉자. MAX가 아니라 MIN이어야 나오는 결과","100번 부서 최고(002)와… 결과에서 빠진 부서가 있음. 세 부서 모두 최고 연봉자가 있음","200번 부서만 나올 이유가 없음"],"t":"'그룹별 최대인 행'은 MAX OVER(PARTITION BY)를 붙인 뒤 원래 값과 같은 행을 고르는 패턴으로 기억하세요."},"1792":{"k":["**LAG**: 이전 행 값 (첫 행 NULL)","**LEAD**: 다음 행 값 (마지막 행 NULL)"],"w":["LEAD는 다음 행 값이라 첫 행에 값이 있고 마지막 행이 NULL","ROW_NUMBER는 순번을 매기는 함수. 인자를 받지 않음","RANK는 순위 함수",""],"t":"결과표에서 NULL이 첫 행에 있으면 LAG, 마지막 행에 있으면 LEAD입니다."},"1793":{"k":["객체 권한 + **WITH GRANT OPTION** → 회수하면 그 사용자가 남에게 준 권한도 **연쇄 회수**","시스템 권한 + WITH ADMIN OPTION → 연쇄 회수 없음","PUBLIC = 모든 사용자"],"w":["WITH GRANT OPTION으로 받으면 자기가 받은 권한을 다른 사용자에게 줄 수 있음. 맞음","GRANT … TO PUBLIC으로 모든 사용자에게 줄 수 있음. 맞음","","권한을 부여한 사용자가 REVOKE로 회수할 수 있음. 맞음"],"t":"GRANT OPTION은 '연쇄', ADMIN OPTION은 '연쇄 없음'. G-연, A-없 으로 짝지어 외우세요."},"1794":{"k":["권한 부여: `GRANT 권한 ON 객체 TO 사용자`","WHERE로 행을 찾는 UPDATE에는 **SELECT + UPDATE** 권한 필요"],"w":["ON 객체가 빠져 어느 테이블 권한인지 없음. 문법 오류","REVOKE는 권한 회수 명령","DENY는 SQL Server에서 권한을 '거부'하는 명령. 부여가 아님",""],"t":"GRANT는 ON(무엇을) + TO(누구에게), REVOKE는 ON + FROM. 전치사 짝만 맞는지 봐도 보기 대부분이 걸러집니다."},"1795":{"k":["**CASCADE**: 연관 객체까지 함께 삭제","**RESTRICT**: 비어 있을(참조가 없을) 때만 삭제"],"w":["NULL은 DROP 옵션이 아님","NOT NULL은 컬럼 제약조건이지 DROP 옵션이 아님","","RESTRICT는 스키마가 비어 있을 때만 삭제되므로 연관 객체까지 지우지 않음"],"t":"'연관된 것까지 모두' = CASCADE. ON DELETE CASCADE, DROP … CASCADE CONSTRAINTS에서도 같은 뜻입니다."},"1796":{"k":["`REVOKE … CASCADE` = 받은 사람이 다시 준 권한까지 회수","회수 후 남은 권한만 실행 가능"],"w":["","INSERT 권한은 CASCADE로 Kim과 Park 모두 회수됨","DELETE 권한도 CASCADE로 Park까지 회수됨","Kim의 INSERT 권한도 회수됨"],"t":"권한 문제는 사람별로 '가진 권한' 표를 만들고 REVOKE가 나올 때마다 지워 가면 정확합니다."},"1797":{"k":["CUBE(A, B) = GROUPING SETS((A,B), (A), (B), **()**)","ROLLUP(A, B) = GROUPING SETS((A,B), (A), ())"],"w":["ROLLUP은 col1별(뒤 컬럼) 소계가 없음","","keyb별, col1별만 있고 (keyb, col1) 상세와 총계가 없음","세 덩어리를 UNION ALL했지만 총계(()) 행이 빠짐"],"t":"CUBE를 다른 형태로 바꾼 보기는 '그룹 4종(둘 다, 앞, 뒤, 전체)'이 다 있는지 체크리스트로 확인하세요."},"1798":{"k":["**INTERSECT** = 교집합, 중복 행은 하나로"],"w":["중복 제거하는 합집합은 UNION","중복을 남기는 합집합은 UNION ALL","","차집합은 MINUS(Oracle) / EXCEPT(SQL Server)"],"t":"집합 연산자 설명은 '합/교/차' + '중복 처리' 두 가지만 맞추면 됩니다."},"1799":{"k":["`LAG(컬럼, n)`: **n칸 앞** 행 값, n 생략 시 1","PARTITION BY 안에서만 앞 행을 봄 (파티션 첫 행들은 NULL)"],"w":["0칸이면 자기 자신 값이 나옴","1칸이면 JONES는 바로 앞 CLARK(2450)가 나와야 함","","4칸 앞이면 MANAGER 파티션(3명)에서는 전부 NULL"],"t":"결과표에서 값이 처음 나오는 행이 파티션의 몇 번째인지 세면 n이 나옵니다. JONES가 3번째에서 처음 값 → n = 2."},"1800":{"k":["RANK: 동점 3명 공동 4위 → 다음은 **7위** (건너뜀)","DENSE_RANK면 다음이 5위"],"w":["DENSE_RANK면 300 다음 400이 5위","","ROW_NUMBER면 1~8로 동점이 없음","PERCENT_RANK는 0~1 사이 비율값"],"t":"동점 인원만큼 다음 순위가 밀렸는지(1,1,3) 바로 이어지는지(1,1,2)만 보세요."},"1801":{"k":["PK 지정: 컬럼 정의 안 `CONSTRAINT 이름 PRIMARY KEY (컬럼)` 또는 `ALTER TABLE … ADD CONSTRAINT 이름 PRIMARY KEY (컬럼)`","모델의 NOT NULL(* 필수)을 그대로 옮겨야 함"],"w":["`ADD PRIMARY KEY 이름 ON (컬럼)`은 없는 문법. ADD CONSTRAINT 이름 PRIMARY KEY (컬럼)","PK 지정은 맞지만 PROD_NM, REG_DT의 NOT NULL이 빠져 모델과 다름","CREATE TABLE 괄호 안에는 ADD를 쓰지 않음. 문법 오류",""],"t":"DDL 보기는 ① 키워드 순서(CONSTRAINT 이름 PRIMARY KEY) ② NOT NULL 누락 ③ ADD 위치 세 가지만 보면 됩니다."},"1802":{"k":["SQL Server: `ALTER TABLE … ALTER COLUMN 컬럼 타입 [NOT NULL]` **한 번에 하나**, 괄호 없이","NOT NULL을 다시 안 쓰면 **NULL 허용으로 바뀜**","Oracle은 MODIFY (괄호로 여러 개 가능)"],"w":["SQL Server는 ALTER COLUMN에 여러 컬럼을 괄호로 묶을 수 없음","괄호로 여러 컬럼을 묶어 문법 오류","분류명에 NOT NULL을 다시 안 써서 NULL 허용으로 바뀜",""],"t":"SQL Server ALTER COLUMN은 '한 줄에 한 컬럼, 제약은 다시 쓰기'. Oracle MODIFY와 구분하세요."},"1803":{"k":["**고립성(Isolation)**: 실행 중 트랜잭션이 다른 트랜잭션의 영향을 받지 않아야 함","커밋 전 값을 다른 트랜잭션이 덮어씀 → 갱신 손실"],"w":["원자성은 '전부 아니면 전무' 문제. 여기선 각 트랜잭션이 끝까지 수행됨","일관성은 무결성 규칙 위배 문제","","영속성(지속성)은 커밋한 결과가 장애에도 남는지의 문제"],"t":"시간표에 TX1, TX2가 번갈아 같은 데이터를 건드리면 거의 고립성 문제입니다."},"1804":{"k":["`ON DELETE CASCADE`: 부모가 지워지면 자식 행도 삭제","`ON DELETE SET NULL`: 부모가 지워지면 자식 FK를 NULL로","연쇄 효과는 단계별로 따라감 (T → S → R)"],"w":["S의 B = 2 행도 C = 1을 참조하므로 같이 삭제되어 R의 (2, 2)도 NULL이 됨","","R은 SET NULL이라 행이 삭제되지 않고 B만 NULL이 됨","R의 B는 NULL로 바뀌어야 함"],"t":"참조 옵션 문제는 화살표를 그려 부모에서 자식 쪽으로 한 단계씩 '삭제/NULL'을 적용하세요."},"1805":{"k":["SQL Server: `SAVE TRANSACTION 이름`, `ROLLBACK TRANSACTION 이름`","저장점 이후 작업만 취소, 이전 작업은 커밋 때 반영"],"w":["sp2 이후 삭제까지 반영되면 0건. 2건이 남는 경우는 없음","keya = 2 외에 한 건을 더 지운 셈","","sp1까지 롤백해야 5건"],"t":"Oracle은 SAVEPOINT / ROLLBACK TO, SQL Server는 SAVE TRANSACTION / ROLLBACK TRANSACTION. 문법만 다르고 동작은 같습니다."},"1806":{"k":["SELECT 결과 중복 제거 = **DISTINCT**","UNIQUE는 제약조건, ORDER BY는 정렬"],"w":["UNIQUE는 컬럼 값 중복을 막는 제약조건 키워드","SORT는 SQL 키워드가 아님","ORDER BY는 정렬만 하고 중복을 없애지 않음",""],"t":"'조회 결과'의 중복 = DISTINCT, '저장 값'의 중복 금지 = UNIQUE."},"1807":{"k":["테이블명: **단수형** 권고, 예약어 불가, 문자로 시작","한 테이블 안 컬럼명 중복 불가","컬럼마다 **데이터 타입 필수**"],"w":["복수형이 아니라 단수형을 권고","같은 테이블 안에서 칼럼명은 중복될 수 없음","","SELECT, TABLE 같은 예약어는 이름으로 쓸 수 없음"],"t":"테이블·컬럼 이름 규칙은 엔터티 명명 규칙(단수형, 유일)과 같은 방향입니다."},"1808":{"k":["MERGE: ON 일치 → UPDATE(+ WHERE) → 그 뒤 **DELETE WHERE**는 **UPDATE된 행**만 대상","불일치 → INSERT(+ WHERE)"],"w":["ADAMS INSERT(CLERK 조건 충족)를 빠뜨린 결과","","DELETE WHERE를 무시해 SMITH가 남았다고 본 결과","INSERT의 CLERK 조건을 무시해 SCOTT·ADAMS·FORD가 모두 들어간 경우"],"t":"MERGE 문제는 원본 행마다 '일치? → UPDATE 조건? → DELETE 조건?' / '불일치? → INSERT 조건?'을 표로 따라가세요. DELETE는 UPDATE된 행에만 걸립니다."},"1809":{"k":["COUNT(*) = 전체 행 수, COUNT(컬럼) = 그 컬럼 NULL 아닌 행 수","PK 컬럼은 NULL이 없으므로 COUNT(PK) = COUNT(*)"],"w":["COUNT(학번)은 학번 기준이라 장학금 NULL과 무관","PK라 NULL이 없어 항상 같음","","학번은 PK라 NULL이 들어갈 수 없음"],"t":"COUNT(컬럼)이 COUNT(*)와 달라질 수 있는지는 '그 컬럼에 NULL이 들어갈 수 있나?' 하나로 판단합니다."},"1810":{"k":["FK: 생성 시 또는 나중에 설정, 한 테이블에 여러 개 가능","FK 값은 **NULL 가능**(선택 관계), 있으면 부모에 존재해야 함(참조 무결성)"],"w":["CREATE TABLE 시 REFERENCES로 설정 가능. 맞음","","한 테이블이 여러 테이블을 참조할 수 있어 여러 개 생성 가능. 맞음","FK는 참조 무결성 제약을 받음. 맞음"],"t":"PK = NULL 불가·중복 불가, FK = NULL 가능·중복 가능. 둘을 대비해서 외우세요."},"1811":{"k":["**후보키**: 유일성 + 최소성을 만족하는 키 (NOT NULL + UNIQUE)","후보키 중 PK로 뽑히지 않은 것 = **대체키**"],"w":["PK는 SalesRepNo로 따로 지정됨","다른 테이블을 참조하는 제약이 없어 외래키 아님","","대리키는 업무 값이 아닌 인위적으로 만든 키(일련번호). RepName은 업무 값"],"t":"UNIQUE + NOT NULL인데 PK가 아니면 '후보키(대체키)'로 바로 연결하세요."},"1812":{"k":["컬럼 삭제: `ALTER TABLE 테이블 DROP COLUMN 컬럼`","컬럼 수정: Oracle MODIFY / SQL Server ALTER COLUMN"],"w":["","REMOVE COLUMN이라는 문법은 없음","MODIFY TABLE이라는 문법은 없음. 테이블 변경은 ALTER TABLE","둘 다 틀림"],"t":"테이블 구조 변경은 항상 ALTER TABLE로 시작합니다. 그 뒤에 ADD / MODIFY / DROP COLUMN / RENAME COLUMN."},"1813":{"k":["DISTINCT는 **SELECT한 컬럼 조합 전체**가 같을 때만 중복","(1, AAAA), (1, BBBB) → 2행"],"w":["DISTINCT 전 원본 4건을 센 값","","COL1 값 종류(1개)만 보고 센 값. DISTINCT는 (COL1, COL2) 조합 기준","원본 4건을 그대로 센 값"],"t":"DISTINCT 뒤에 컬럼이 여러 개면 '행 전체'를 비교한다고 생각하세요. 한 컬럼만 같아서는 중복이 아닙니다."},"1814":{"k":["Oracle 주요 타입: **CHAR · VARCHAR2 · NUMBER · DATE**","TEXT는 SQL Server·MySQL 쪽 타입"],"w":["","CHAR는 Oracle 고정 길이 문자 타입","VARCHAR2는 Oracle 가변 길이 문자 타입","NUMBER는 Oracle 숫자 타입"],"t":"Oracle 문자 타입은 이름에 CHAR가 들어갑니다(CHAR, VARCHAR2, CLOB). TEXT가 보이면 Oracle이 아니에요."},"1815":{"k":["입력(Insert) 참조동작: Automatic · Set Null · Set Default · **Dependent**(부모 PK가 있을 때만 입력)","삭제(Delete) 참조동작: Cascade · Set Null · Set Default · Restrict"],"w":["CASCADE는 부모 삭제·수정 시 자식에도 같이 적용하는 삭제 쪽 동작","RESTRICT도 삭제 쪽 동작. 자식이 있으면 부모 삭제를 막음","AUTOMATIC은 부모 PK가 없으면 부모를 먼저 만들어 주고 자식을 입력",""],"t":"'입력을 허용하지 않는다(부모가 있어야 의존해서 들어감)' = Dependent. 이름 그대로 '의존'입니다."},"1816":{"k":["컬럼 목록을 생략한 INSERT는 **모든 컬럼 값을 순서대로**","NOT NULL 컬럼은 반드시 값 필요","길이 초과(VARCHAR2(1)에 'AB')는 오류"],"w":["(가) 컬럼 생략 시 3개 값을 다 줘야 하는데 2개뿐. (나) VARCHAR2(1)에 'AB'는 길이 초과","(다) NOT NULL인 AMT를 넣지 않아 오류","(다)가 오류",""],"t":"INSERT 오류는 세 가지 체크: 값 개수, NOT NULL 누락, 길이·타입 초과. 보기마다 이 셋만 확인하세요."},"1817":{"k":["INSERT에서 빠진 컬럼은 DEFAULT, 없으면 **NULL** → NOT NULL 컬럼이면 오류","숫자 → 문자 컬럼은 자동 변환되어 들어감"],"w":["숫자 1은 VARCHAR2로 자동 변환되고 모든 컬럼에 값이 들어감. 정상","","존재하는 행의 USE_YN만 바꾸는 정상 UPDATE","200이 VARCHAR2로 자동 변환되어 정상 UPDATE"],"t":"컬럼 목록을 적은 INSERT는 목록에 '없는' 컬럼부터 보세요. 그중 NOT NULL이면서 DEFAULT 없는 게 있으면 오류입니다."},"1818":{"k":["DATE 컬럼에 **숫자**는 바로 넣을 수 없음 (오류)","문자열은 NLS 날짜 형식과 맞으면 자동 변환","날짜 연산 SYSDATE - 1 가능"],"w":["SYSDATE로 날짜를 넣은 정상 INSERT","문자 '20190301'은 날짜 형식이 맞으면 묵시적으로 DATE 변환","SYSDATE - 1은 어제 날짜로 정상",""],"t":"묵시적 변환은 문자 ↔ 숫자, 문자 ↔ 날짜는 되지만 숫자 → 날짜는 안 됩니다."},"1819":{"k":["산술 우선순위: **() → *, / → +, −** (수학과 같음)"],"w":["괄호가 가장 먼저","덧셈·뺄셈이 곱셈·나눗셈보다 먼저일 수 없음","","+, −가 *, / 보다 먼저일 수 없음"],"t":"산술은 학교 수학 순서 그대로입니다. 헷갈리는 건 산술이 아니라 NOT·AND·OR 쪽이에요."},"1820":{"k":["FK는 **자식 테이블**(참조하는 쪽)에 정의","`ON DELETE CASCADE`: 부모 삭제 시 자식도 삭제"],"w":["RESTRICT는 자식이 있으면 부모 삭제를 막음. 같이 삭제가 아님","FK는 Department가 아니라 자식인 Employee에 걸어야 함","","방향도 반대이고 RESTRICT라 삭제도 막힘"],"t":"FOREIGN KEY는 '내가 남을 참조한다'는 선언이라 항상 자식 테이블 CREATE 문에 들어갑니다."},"1821":{"k":["DELETE: 행 삭제, 구조 유지, 롤백 가능(사용자 COMMIT)","TRUNCATE: 전체 행 삭제, 구조 유지, UNDO 없음(빠름), 자동 커밋","DROP: **테이블 정의까지** 삭제, 자동 커밋"],"w":["","DROP은 테이블 정의 삭제, TRUNCATE는 처음 만든 상태로 초기화. 맞음","TRUNCATE는 UNDO를 만들지 않아 DELETE보다 빠름. 맞음","DROP·TRUNCATE는 DDL이라 자동 커밋, DELETE는 사용자가 COMMIT. 맞음"],"t":"세 명령 비교는 '지운 뒤 테이블이 남아 있나?'로 먼저 나누세요. DELETE·TRUNCATE는 남고 DROP만 사라집니다."},"1822":{"k":["지속성 = **성공적으로 완료(COMMIT)된** 결과가 영구 보존","취소된 트랜잭션은 반영되지 않음 (원자성)"],"w":["모두 실행되거나 전혀 실행되지 않음. 원자성 정의 맞음","실행 전후로 DB가 일관된 상태 유지. 일관성 정의 맞음","다른 트랜잭션의 영향을 받지 않음. 고립성 정의 맞음",""],"t":"ACID 정의 문제는 각 성질의 '조건'을 확인하세요. 지속성은 '커밋된' 결과에만 해당합니다."},"1823":{"k":["**Oracle**: DDL 실행 시 직전 DML까지 **자동 커밋**, DDL 자체도 확정","**SQL Server**: DDL도 트랜잭션 안에 포함 → ROLLBACK으로 함께 취소","(AUTO COMMIT FALSE 조건)"],"w":["Oracle은 CREATE TABLE 실행 시 묵시적 COMMIT이 일어나 UPDATE가 확정됨. 맞음","SQL Server는 DDL로 커밋되지 않아 ROLLBACK이 UPDATE를 취소함. 맞음","","SQL Server는 CREATE TABLE도 트랜잭션에 포함돼 함께 롤백. 맞음"],"t":"Oracle에서 DDL은 '커밋 버튼'과 같습니다. DDL 앞뒤로 무엇이 확정되는지만 따지면 됩니다."},"1824":{"k":["**트랜잭션** = DB의 논리적 연산(작업) 단위","뷰 = 가상 테이블, 프로시저 = 저장된 SQL 블록, 트리거 = 이벤트 시 자동 실행"],"w":["뷰는 SELECT를 저장해 둔 가상 테이블","","프로시저는 이름을 붙여 저장한 SQL 처리 블록","트리거는 INSERT·UPDATE·DELETE 같은 이벤트에 자동으로 실행되는 블록"],"t":"'논리적 작업 단위', '연산 단위'라는 말은 트랜잭션의 정의 문구입니다."},"1825":{"k":["SQL Server: 이름 없는 **ROLLBACK**은 중첩된 BEGIN TRAN까지 **커밋 안 된 작업 전부** 취소","이미 COMMIT한 작업은 그대로"],"w":["모든 행이 바뀌거나 삭제된 경우는 없음","002 삭제는 남고 UPDATE만 롤백됐다고 본 값. ROLLBACK은 바깥 트랜잭션까지 전부 취소","","ROLLBACK을 무시하고 UPDATE까지 반영한 값"],"t":"SQL Server의 ROLLBACK(이름 없음)은 가장 바깥 트랜잭션까지 한 번에 되돌립니다. 중첩 BEGIN이 몇 개든 상관없어요."},"1826":{"k":["`ROLLBACK TRANSACTION SP2` = SP2 **이후** 작업만 취소","SP2 이전 작업은 COMMIT 때 확정"],"w":["SP1로 롤백해야 원래 값 TV가 됨","","SP2 이후 '평면-TV' 변경은 취소됨","SAVE TRANSACTION은 SQL Server의 정상 문법이라 오류 아님"],"t":"저장점 문제는 '롤백 지점 바로 앞까지의 상태'가 최종 답입니다."},"1827":{"k":["**TOP(n) WITH TIES**: n번째와 같은 값까지 포함 (ORDER BY 필수)","Oracle은 FETCH FIRST n ROWS WITH TIES","ROWNUM은 정렬 전에 붙음"],"w":["WITH TIES가 없어 공동 3위(D팀, F팀) 중 한 팀만 나옴","ORDER BY가 없어 승리건수와 상관없는 아무 3건","ROWNUM이 정렬 전에 붙어 임의의 3건을 뽑은 뒤 정렬",""],"t":"'동점까지 함께'라는 말이 나오면 WITH TIES를 찾으세요. 그리고 WITH TIES 뒤에는 ORDER BY가 꼭 있어야 합니다."},"1828":{"k":["UPDATE … SET = (서브쿼리)에 **WHERE가 없으면 모든 행** 대상 → 짝 없는 행은 NULL로 바뀜","대상 제한: `WHERE 부서코드 IN (SELECT … FROM 부서임시)`","부서별 최신 = 연관 서브쿼리로 MAX(변경일자)"],"w":["WHERE가 없어 A007·A008 외 모든 부서 담당자가 NULL이 되고, 담당자 자리에 부서코드를 넣는 것도 틀림","WHERE EXISTS가 부서 테이블 자신을 보니 모든 행이 대상 → 나머지 부서 NULL, 부서코드를 넣는 문제도 그대로","","WHERE가 없어 나머지 부서가 NULL이 되고, 날짜를 고정값으로 박아 '가장 최근' 조건도 못 지킴"],"t":"서브쿼리로 값을 바꾸는 UPDATE는 항상 'WHERE로 대상 행을 제한했나'부터 보세요. 없으면 짝 없는 행이 NULL로 덮입니다."},"1":{"k":["모델링 3대 특징: **추상화 · 단순화 · 명확화** (단추명)","구체화는 모델링 단계가 내려갈수록(개념→물리) 높아지는 '수준'이지 특징이 아님"],"w":["단순화는 복잡한 현실을 제한된 표기법으로 쉽게 표현하는 것. 3대 특징 중 하나","추상화는 현실의 공통 성질만 뽑아 일정한 형식으로 표현하는 것. 3대 특징","명확화는 애매함 없이 한 가지 의미로 읽히게 하는 것. 3대 특징",""],"t":"특징 3개는 '단추명'. 보기에 '구체화', '정규화', '일반화'처럼 비슷한 '~화'가 섞여 나오니 세 단어를 정확히 외우세요."},"2":{"k":["유의사항: **중복 · 비유연성 · 비일관성**을 피하기","조회 성능을 위해 일부러 중복을 두는 건 반정규화(물리 단계)이지 모델링 원칙이 아님"],"w":["같은 데이터를 여러 곳에 저장하지 않는 것은 '중복' 유의사항의 올바른 대응","데이터 정의와 프로세스를 분리하는 것은 '비유연성' 유의사항의 대응","연관 관계를 명확히 정의하는 것은 '비일관성' 유의사항의 대응",""],"t":"'성능을 위해 중복 저장'은 유의사항이 아니라 반정규화 이야기입니다. 모델링 원칙 문제에서 나오면 오답."},"3":{"k":["모델링 3관점: **데이터(What) · 프로세스(How) · 상관(Interaction)**","성능은 물리 모델링에서 고려하는 요소"],"w":["","데이터 관점은 업무에 어떤 데이터가 있는지 보는 관점. 3대 관점","프로세스 관점은 업무가 실제로 무엇을 하는지 보는 관점. 3대 관점","상관 관점은 업무 처리에 따라 데이터가 어떻게 영향받는지 보는 관점. 3대 관점"],"t":"관점 문제의 오답은 거의 항상 '성능', '사용자', '기술' 관점입니다."},"4":{"k":["상관 관점 = 프로세스가 데이터를 어떻게 **생성·조회·수정·삭제**하는지","도구: **CRUD 매트릭스**"],"w":["정규화는 논리 모델링에서 중복을 없애는 작업. 데이터 구조 쪽 일","","인덱스 설계는 물리 설계 작업","반정규화는 성능을 위한 물리 단계 작업"],"t":"상관 관점 = CRUD 매트릭스. 이 짝은 거의 그대로 시험에 나옵니다."},"18":{"k":["모델링이 중요한 이유: **파급효과 · 간결한 표현 · 데이터 품질**","모델이 SQL 성능을 자동으로 보장하지는 않음"],"w":["나중에 모델을 바꾸면 영향이 크다는 파급효과(Leverage)는 실제 이유","","복잡한 요구사항을 간결하게 표현(Conciseness)하는 것도 중요한 이유","데이터 품질(Data Quality) 확보도 중요한 이유"],"t":"중요성 3가지는 영어 단어(Leverage, Conciseness, Data Quality)로도 나옵니다. '자동으로 보장'은 언제나 의심."},"20":{"k":["모델링은 시스템 구축의 기반이면서 **업무 분석·형상화** 도구"],"w":["현실 세계를 단순화해 표현하는 게 모델링의 정의","업무를 분석하고 형상화하는 데 쓰는 것이 모델링의 용도","정보시스템 구축의 기반이 된다는 것도 맞음",""],"t":"'~만을 위해'처럼 용도를 하나로 좁히는 문장은 오답 패턴입니다."},"479":{"k":["모델링 = 현실을 **필요한 만큼** 단순화·추상화해 약속된 표기법으로 표현"],"w":["모든 정보를 그대로 옮기는 게 아니라 필요한 것만 골라 단순화함","모델링은 DBMS 설치와 무관하게 업무 분석 단계부터 함","모델링은 설계 작업이지 프로그램 코드 작성 단계가 아님",""],"t":"'모든', '빠짐없이 그대로'는 추상화·단순화와 반대되는 말입니다."},"480":{"k":["**중복**: 같은 데이터를 여러 엔터티에 저장하는 문제"],"w":["비유연성은 업무가 바뀔 때 모델이 쉽게 흔들리는 문제","비일관성은 연관 데이터를 일부만 고쳐 서로 모순되는 문제","추상화는 유의사항이 아니라 모델링의 특징",""],"t":"'여러 곳에 같은 데이터' → 중복, '업무 변화에 약함' → 비유연성, '서로 모순' → 비일관성."},"481":{"k":["**비유연성**: 업무 규칙이 바뀔 때마다 모델을 크게 고쳐야 하는 문제","대응: 데이터 정의와 프로세스를 분리"],"w":["중복은 같은 데이터를 여러 곳에 저장하는 문제","명확화는 유의사항이 아니라 모델링 특징","비일관성은 연관 데이터 간 모순 문제",""],"t":"'변화', '유연하게', '자주 변경'이 나오면 비유연성입니다."},"482":{"k":["관점은 **데이터 · 프로세스 · 상관** 세 가지뿐"],"w":["데이터 관점 = 업무가 어떤 데이터와 관련 있는지. 맞는 연결","프로세스 관점 = 업무가 실제로 하는 일. 맞는 연결","상관 관점 = 업무 처리 방법에 따라 데이터가 받는 영향. 맞는 연결",""],"t":"연결 문제도 결국 '없는 관점'을 찾는 문제입니다. 성능 관점을 바로 고르세요."},"483":{"k":["단순화 = **쉽게** / 추상화 = **핵심(공통 성질)만** / 명확화 = **애매함 제거**"],"w":["약속된 규칙으로 쉽게 표현하는 건 단순화","일정한 형식으로 핵심만 표현하는 건 추상화","중복 없이 저장하는 건 특징이 아니라 유의사항(중복)",""],"t":"세 특징을 각각 한 단어로 바꿔 두세요. 단순화-쉽게, 추상화-핵심, 명확화-한 가지 뜻."},"542":{"k":["CRUD 매트릭스: 프로세스 × 엔터티 표에 C·R·U·D를 표시","용도: 어떤 엔터티가 어떤 프로세스에서 쓰이는지 **누락 없이 검증** (상관 관점)"],"w":["CRUD 매트릭스는 실행 속도를 보여 주지 않음","정규형 단계는 함수 종속으로 판단하는 것이라 무관","","사용자 권한 체계는 DCL·보안 설계 영역"],"t":"CRUD 매트릭스에서 C가 하나도 없는 엔터티는 '누가 만드는지 모르는' 엔터티라는 뜻입니다. 검증 도구라는 점을 기억하세요."},"1061":{"k":["데이터 정의를 사용 프로세스와 **분리** → **비유연성** 감소"],"w":["중복은 같은 정보를 여러 곳에 저장하는 문제라 대응책이 다름","비정형성은 모델링 유의점 용어가 아님","비일관성은 연관 데이터 간 불일치 문제",""],"t":"'프로세스와 분리'라는 대응책이 보이면 비유연성으로 연결하세요."},"1062":{"k":["상관 관점 = 업무 처리 **방법에 따라 데이터가 받는 영향** (Interaction)"],"w":["데이터 관점은 업무가 어떤 데이터와 관련 있는지(What)","프로세스 관점은 업무가 실제로 하는 일(How)","사용자 관점은 3대 관점이 아님",""],"t":"'~에 따라 데이터가 영향을 받는다'처럼 둘의 관계를 말하면 상관 관점입니다."},"1183":{"k":["3관점: 데이터(What) · 프로세스(How) · 상관(Interaction)"],"w":["데이터 관점은 3대 관점 중 하나","프로세스 관점은 3대 관점 중 하나","","상관 관점은 3대 관점 중 하나"],"t":"관점 문제는 '성능'을 찾으면 끝입니다."},"1184":{"k":["모델은 업무가 바뀌면 **함께 바뀜**","물리 단계에서는 용량 산정·저장 구조도 정함"],"w":["단순화·추상화로 현실을 표현한다는 건 모델링 정의 그대로","현업과 소통하는 커뮤니케이션 도구라는 것도 맞음","물리 모델링 단계에서 데이터 용량 산정을 하는 것도 맞음",""],"t":"'한 번 확정되면 수정하지 않는다' 같은 고정된 표현은 모델링 문제에서 거의 오답입니다."},"1324":{"k":["업무 규칙(주문은 반드시 고객이 있다 등)은 관계·선택사양으로 **모델에 반영**","모델은 현업과의 의사소통 도구"],"w":["","업무 규칙은 관계의 필수/선택 등으로 모델에 담아야 함","모델은 현업과 개발자가 함께 보는 소통 도구","필요한 것만 골라 단순화·추상화함. 모든 데이터를 그대로 옮기지 않음"],"t":"모델링 정의 문제의 정답은 대개 '업무 규칙 반영', '의사소통 도구', '단순화·추상화' 쪽입니다."},"1412":{"k":["프로세스 관점 = **How** (업무가 실제로 하는 일)"],"w":["","데이터 관점은 What(어떤 데이터인가)","상관 관점은 Interaction(처리에 따라 데이터가 받는 영향)","기술 관점은 3대 관점이 아님"],"t":"What-데이터, How-프로세스, Interaction-상관. 영어 한 단어씩 짝지어 두세요."},"1413":{"k":["같은 정보를 여러 곳에 저장 = **중복**(원인)","그 결과 일부만 수정돼 서로 달라짐 = 비일관성(결과)"],"w":["독립성은 모델링 유의점이 아님","비유연성은 업무 변화에 모델이 흔들리는 문제","비일관성은 결과로 나타난 증상. 문제의 원인은 중복 저장",""],"t":"'원인'을 묻는지 '현상'을 묻는지 보세요. 여러 곳에 저장한 게 원인(중복), 값이 어긋나는 게 결과(비일관성)."},"1460":{"k":["명확화 = 애매함 없이 **한 가지 의미**로 해석되게"],"w":["","단순화는 제한된 표기법으로 쉽게 표현하는 것","추상화는 공통 성질로 일반화하는 것","정규화는 모델링 특징이 아니라 논리 모델링 작업"],"t":"'한 가지 의미', '정확하게', '애매함 없이' → 명확화."},"5":{"k":["모델링 단계: **개념 → 논리 → 물리** (개논물)","추상적인 것에서 구체적인 것으로"],"w":["논리 모델은 개념 모델을 구체화한 다음 단계라 맨 앞일 수 없음","가장 구체적인 물리 모델이 맨 앞에 와서 순서가 거꾸로","","물리 설계는 논리 모델(키·정규화)이 확정된 뒤에 함"],"t":"'개논물' 세 글자만 외우면 순서 문제는 끝입니다."},"6":{"k":["추상화 수준: **개념 > 논리 > 물리**","물리가 가장 구체적"],"w":["","논리 모델은 키·속성·정규화까지 들어가 개념보다 구체적","물리 모델은 가장 구체적인 단계","단계마다 추상화 수준이 다름"],"t":"추상화는 '얼마나 뭉뚱그렸나'입니다. 처음(개념)이 가장 뭉뚱그려져 있어요."},"7":{"k":["**논리** 모델링: 키·속성·관계 확정 + **정규화**","개념: 핵심 엔터티·관계 / 물리: 저장 구조·반정규화"],"w":["개념 모델링은 핵심 엔터티와 관계만 잡는 단계","","물리 모델링은 정규화 이후 성능·저장 구조를 설계하는 단계(반정규화 쪽)","구현 단계는 모델링 단계에 포함되지 않음"],"t":"정규화-논리, 반정규화-물리. 이 짝은 반드시 외워 두세요."},"8":{"k":["**물리** 모델링: 테이블·인덱스·파티션 등 DBMS 저장 구조, 성능·용량 고려"],"w":["개념 모델링은 업무 핵심 엔터티 수준의 추상적 설계","논리 모델링은 키·속성·정규화까지이고 DBMS 저장 구조는 다루지 않음","외부 스키마는 사용자 관점의 데이터 정의(뷰)",""],"t":"'DBMS', '인덱스', '파티션', '용량'이라는 단어가 보이면 물리 단계입니다."},"9":{"k":["데이터 모델 3요소: **엔터티 · 속성 · 관계**","인덱스는 물리 설계 대상"],"w":["","엔터티는 3요소 중 하나","속성은 3요소 중 하나","관계는 3요소 중 하나"],"t":"3요소는 '어떤 것(엔터티) – 그 성격(속성) – 서로의 관계'. 물리 객체(인덱스, 뷰)가 섞이면 그게 답."},"10":{"k":["ERD 순서: 엔터티 **도출** → 배치 → 관계 설정 → 관계명 → 관계차수 → **선택사양** (도배설명차선)"],"w":["첫 단계는 배치가 아니라 엔터티 도출","관계 설정은 세 번째, 관계차수는 다섯 번째 단계","","관계 설정은 마지막이 아니라 세 번째"],"t":"처음과 끝만 물으면 '도'와 '선'. 도출로 시작해서 선택사양으로 끝납니다."},"11":{"k":["도배설명차선: **도**출 → **배**치 → 관계 **설**정 → 관계**명** → 관계**차**수 → **선**택사양"],"w":["","엔터티를 도출해야 배치할 수 있으므로 도출이 먼저","관계를 설정해야 이름을 붙일 수 있고, 차수 다음이 선택사양","엔터티 배치를 마친 뒤에 관계를 설정함"],"t":"논리로 풀어도 됩니다. 뽑고(도출) → 놓고(배치) → 잇고(설정) → 이름 붙이고 → 몇 개인지 → 필수인지."},"421":{"k":["정규화 = 논리 단계, 논리 모델은 재사용성 높음","물리로 갈수록 **구체화**","ERD는 **개념** 단계에서 처음 작성"],"w":["개념 단계는 핵심 엔터티와 관계만 잡고 정규화는 하지 않음","","물리로 갈수록 추상화 수준은 낮아지고 구체적이 됨","ERD는 개념 단계부터 작성함"],"t":"단계 설명 문제는 '정규화-논리', '구체화-물리 쪽', 'ERD 시작-개념' 세 가지로 대부분 걸러집니다."},"484":{"k":["**개념적** 모델링: 전사적 관점, 핵심 엔터티·관계 도출, 추상화 수준 최고"],"w":["운영 단계는 모델링 단계가 아님","논리 모델링은 키·속성 확정과 정규화 단계","물리 모델링은 저장 구조 설계 단계",""],"t":"'전사적', '핵심 엔터티', 'EA'가 나오면 개념적 모델링입니다."},"485":{"k":["논리 모델링: 식별자 확정 · 정규화 · 재사용성 높음","인덱스·파티션 같은 저장 구조는 **물리**"],"w":["식별자(키)를 확정하는 것은 논리 모델링의 일. 맞음","정규화를 수행하는 것도 논리 모델링. 맞음","특정 DBMS에 묶이지 않아 재사용성이 높음. 맞음",""],"t":"논리 단계 설명에 DBMS 종속적인 단어(인덱스, 파티션, 저장 공간)가 섞이면 그게 오답입니다."},"486":{"k":["개념 → 논리 → 물리로 갈수록 **구체화↑ · 추상화↓**","DBMS 고려는 물리에서 가장 많고, 재사용성은 논리가 가장 높음"],"w":["추상화 수준은 개념 단계가 가장 높고 물리로 갈수록 낮아짐","물리로 갈수록 특정 DBMS 특성을 더 많이 반영함","재사용성은 DBMS에 묶이지 않는 논리 모델이 높고 물리는 낮아짐",""],"t":"물리 쪽으로 갈수록 '구체화, DBMS 종속, 재사용성↓' 세 가지가 함께 움직인다고 묶어 두세요."},"487":{"k":["도배설명차선: 도출 → 배치 → 관계 **설**정 → 관계**명** → 차수 → 선택사양"],"w":["엔터티 배치는 관계 설정보다 앞 단계","선택사양은 맨 마지막 단계","관계차수는 관계명을 붙인 다음 단계",""],"t":"'설' 다음은 '명'. 관계를 이었으면 바로 이름부터 붙인다고 기억하세요."},"488":{"k":["배치 원칙: 핵심(중심) 엔터티를 **왼쪽 위**, 관련 엔터티를 주변·오른쪽·아래로","읽는 흐름(왼→오, 위→아래)과 가독성을 고려"],"w":["배치의 목적 자체가 가독성. 무관하지 않음","이름순 배치라는 원칙은 없음","관계가 많은 핵심 엔터티는 구석이 아니라 왼쪽 위 중심에 둠",""],"t":"ERD도 글처럼 왼쪽 위에서 읽기 시작합니다. 그래서 가장 중요한 엔터티를 거기에 둡니다."},"541":{"k":["테이블스페이스·인덱스·파티션·용량 = **물리** 모델링","논리 = DBMS 비종속, 키·속성·정규화"],"w":["개념 모델링은 업무 중심이고 포괄적. 맞는 설명","논리 모델링은 특정 DBMS에 종속되지 않음. 맞는 설명","물리 모델링은 성능·저장 공간·보안을 고려. 맞는 설명",""],"t":"'테이블스페이스'는 DBMS 저장 단위라서 논리 단계 설명에 나오면 무조건 틀린 문장입니다."},"1063":{"k":["논리 모델링 대표 활동: **정규화**, 식별자 확정, 속성·관계 상세화","용량·테이블스페이스·인덱스·파티션은 물리"],"w":["저장 용량 산정은 물리 모델링 활동","테이블스페이스 설계는 물리 모델링 활동","인덱스·파티션 설계는 물리 모델링 활동",""],"t":"보기 셋이 같은 성격(물리)이고 하나만 다르면 그 하나가 답인 경우가 많습니다."},"1141":{"k":["물리 모델링: **DBMS 특성 + 성능** 고려, 테이블·인덱스·저장 구조 설계"],"w":["추상화 수준 최고·업무 중심은 개념 모델링","핵심 엔터티와 관계만 뽑는 건 개념 모델링","정규화는 논리 모델링에서 수행",""],"t":"단계별 키워드: 개념-추상화·핵심, 논리-정규화·키, 물리-DBMS·성능·저장."},"1227":{"k":["DBMS 특성·성능·저장 구조 = **물리적** 데이터 모델링"],"w":["개념적 모델링은 핵심 엔터티와 관계를 추상적으로 표현","논리적 모델링은 키·속성·관계를 정확히 표현(DBMS 비종속)","","업무 프로세스 모델링은 데이터 모델링 3단계에 속하지 않음"],"t":"'실제 구현할 수 있게'라는 표현은 물리 단계를 가리킵니다."},"12":{"k":["ANSI/SPARC 3단계: **외부 · 개념 · 내부** 스키마","논리·물리·관계 스키마는 3단계 이름이 아님"],"w":["외부 스키마는 사용자 관점 단계","","개념 스키마는 전체 통합 관점 단계","내부 스키마는 저장 장치 관점 단계"],"t":"3단계 이름 세 개(외·개·내)를 외워 두면, 그 외의 '~스키마'는 전부 오답입니다."},"13":{"k":["외부 스키마 = 사용자·응용 프로그램별 관점(뷰), **여러 개**","개념·내부 스키마는 DB당 **하나**"],"w":["","개념 스키마는 DB 전체를 통합한 구조라 하나뿐","내부 스키마는 물리 저장 구조라 하나뿐","메타 스키마는 3단계 스키마 용어가 아님"],"t":"'여러 개 존재'는 외부 스키마만 해당합니다. 사용자마다 보는 화면이 다르기 때문이에요."},"14":{"k":["개념 스키마 = 모든 사용자 관점을 **통합**한 전체 논리 구조, DB당 하나"],"w":["외부 스키마는 사용자별 관점이라 여러 개","내부 스키마는 저장 장치 관점의 물리 구조","","서브 스키마는 외부 스키마의 다른 이름"],"t":"'통합', '전체', '조직 전체', 'DBA 관점' → 개념 스키마."},"15":{"k":["내부 스키마 = 저장 장치 관점: 레코드 구조, 인덱스, 저장 위치"],"w":["외부 스키마는 사용자가 보는 관점","","개념 스키마는 전체 논리 구조로 저장 방식은 다루지 않음","사용자 스키마는 외부 스키마 쪽 개념"],"t":"'디스크', '물리적 저장', '레코드 형식', '인덱스' → 내부 스키마."},"16":{"k":["**논리적 독립성**: 개념 스키마가 바뀌어도 외부 스키마(응용)는 그대로","**물리적 독립성**: 내부 스키마가 바뀌어도 개념 스키마는 그대로"],"w":["물리적 독립성은 내부 스키마 변경이 개념 스키마에 영향을 주지 않는 성질","","외부적 독립성이라는 용어는 없음","개념적 독립성이라는 용어는 없음"],"t":"독립성은 '논리적', '물리적' 두 개뿐입니다. 바뀐 쪽이 개념이면 논리적, 내부면 물리적."},"17":{"k":["저장 장치·인덱스 변경(내부 스키마) → 응용·개념 무영향 = **물리적 독립성**"],"w":["논리적 독립성은 개념 스키마 변경으로부터 외부를 보호하는 성질","개념적 독립성이라는 용어는 없음","","외부적 독립성이라는 용어는 없음"],"t":"'저장', '디스크', '인덱스'가 바뀌는 상황이면 물리적 독립성입니다."},"19":{"k":["데이터 독립성의 목적: 한 계층의 변경이 다른 계층에 **번지지 않게** → 유지보수 비용 감소","중복 저장·속도 향상과는 무관"],"w":["사용자마다 독립적인 뷰를 주는 것은 3단계 구조의 목적","저장 구조가 바뀌어도 응용 수정이 적은 건 물리적 독립성의 목적","","변경 영향이 줄어 유지보수 비용이 줄어드는 것도 목적"],"t":"독립성 문제에서 '중복 저장', '조회 속도'가 보이면 오답입니다. 독립성은 '변경 영향 차단' 이야기예요."},"422":{"k":["외부 ↔ 개념 사상 = **논리적** 독립성","개념 ↔ 내부 사상 = **물리적** 독립성"],"w":["논리적 독립성은 외부↔개념 사이 사상이 보장","","외부적 독립성이라는 용어는 없음","개념적 독립성이라는 용어는 없음"],"t":"사상(매핑)은 경계마다 하나씩, 총 두 개입니다. 아래쪽 경계(개념-내부)가 물리적."},"489":{"k":["저장 위치·인덱스 변경 = 내부 스키마 변경 → 그래도 SQL·프로그램 무수정 = **물리적 독립성**"],"w":["논리적 독립성은 개념 스키마(테이블 구조)가 바뀌는 상황","외부적 독립성은 없는 용어","개념적 독립성은 없는 용어",""],"t":"상황 문제는 '무엇이 바뀌었나'만 찾으세요. 디스크·인덱스면 물리적."},"490":{"k":["전사 데이터 구조(엔터티·속성) 변경 = 개념 스키마 변경 → 사용자 뷰 그대로 = **논리적 독립성**"],"w":["물리적 독립성은 저장 구조가 바뀌는 상황","내부적 독립성은 없는 용어","","저장 독립성은 없는 용어"],"t":"엔터티·속성·컬럼이 추가되는 건 개념 스키마 변화입니다. 그래서 논리적 독립성."},"491":{"k":["DBA 관점 · DB 전체를 통합한 논리 구조 = **개념 스키마**"],"w":["외부 스키마는 개별 사용자 관점","서브 스키마는 외부 스키마의 다른 이름","내부 스키마는 저장 장치 관점",""],"t":"관점 주체로 외워도 됩니다. 사용자-외부, DBA(통합)-개념, 저장 장치-내부."},"492":{"k":["외부 **여러 개** · 개념 **하나** · 내부 = 물리 저장 구조","개념 스키마가 가운데서 외부와 내부를 분리 → 독립성"],"w":["외부 스키마는 사용자마다 있어 여러 개","개념 스키마는 통합 구조라 하나","","외부와 내부는 개념 스키마를 사이에 두고 분리돼 독립성이 생김"],"t":"개수 문제가 자주 나옵니다. 외부만 여러 개, 나머지는 하나."},"555":{"k":["데이터 독립성 = 한 계층 변경이 다른 계층에 주는 **영향 차단**"],"w":["여러 곳에 저장하는 것(중복)과 독립성은 무관","","SQL 문법 단순화와 무관","DBMS 종류 통일과 무관"],"t":"독립성의 정답 키워드는 '변경 영향 최소화', '유지보수 비용 감소'입니다."},"1064":{"k":["외부 = 사용자별(서브 스키마) / 개념 = **조직 전체 통합** / 내부 = 물리 저장"],"w":["","외부 스키마는 사용자별 관점이라 통합 구조가 아님","내부 스키마는 물리 저장 구조","서브 스키마는 외부 스키마의 다른 이름"],"t":"서브 스키마 = 외부 스키마. 이 동의어가 보기로 자주 섞여 나옵니다."},"1140":{"k":["컬럼 추가 = 테이블 구조 변경 = **개념 스키마** 변경","그래도 사용자 뷰·프로그램이 그대로 = **논리적 독립성**","파티션·인덱스 변경이면 내부 스키마 → 물리적 독립성"],"w":["컬럼 추가는 저장 구조가 아니라 논리 구조 변경이라 내부 스키마가 아님","변경된 건 외부가 아니라 개념 스키마. 외부는 그대로 유지됨","개념 스키마 변경으로 보장되는 건 논리적 독립성",""],"t":"독립성 문제는 '변경된 스키마'와 '보호된 스키마'를 구분하세요. 개념이 바뀌고 외부가 보호되면 논리적."},"1274":{"k":["외부 = 사용자·응용별 데이터 정의","개념 = 조직 전체 통합 구조","내부 = 물리 저장 구조와 접근 방법 (사용자 관점 아님)"],"w":["라(내부 스키마=물리 저장 구조)도 맞는 설명이라 빠지면 안 됨","다는 외부 스키마 설명을 내부에 붙인 틀린 문장","","다는 틀린 설명이라 들어가면 안 됨"],"t":"'모두 고른 것' 문제는 틀린 문장 하나(다)를 먼저 찾고, 그게 빠진 보기 중 가장 많이 담은 걸 고르세요."},"1323":{"k":["3단계 = 외부 · 개념 · 내부","'논리/물리'는 **모델링 단계** 이름"],"w":["외부 스키마는 3단계 중 하나","","내부 스키마는 3단계 중 하나","개념 스키마는 3단계 중 하나"],"t":"모델링 단계(개념·논리·물리)와 스키마 단계(외부·개념·내부)를 섞어서 내는 함정입니다. '개념'만 겹쳐요."},"1364":{"k":["테이블스페이스·인덱스·파티션 = **내부**","부서별 VIEW = **외부**","전사 통합 ERD = **개념**"],"w":["","㉠은 저장 구조라 개념이 아니라 내부, ㉢은 통합 구조라 개념","㉠과 ㉡이 뒤바뀜. 저장 설계서는 내부, VIEW는 외부","㉡ VIEW는 외부, ㉢ 통합 ERD는 개념"],"t":"VIEW는 대표적인 외부 스키마 예시입니다. 시험에 자주 나와요."},"1554":{"k":["내부 스키마 = 저장 장치에 **실제로 저장되는 물리 구조**, DB당 하나"],"w":["사용자마다 다른 관점은 외부 스키마","여러 개 존재하는 건 외부 스키마","","조직 전체 통합 관점은 개념 스키마"],"t":"세 스키마 정의 문제는 키워드 대응으로 끝납니다: 사용자-외부, 통합-개념, 저장-내부."},"21":{"k":["엔터티 6특징: 업무 필요 · 식별자 · **인스턴스 2개 이상** · 속성 2개 이상 · 업무 프로세스에서 사용 · 관계 1개 이상"],"w":["업무에서 관리할 정보여야 한다는 건 엔터티의 특징","유일한 식별자로 구분돼야 한다는 것도 특징","","다른 엔터티와 관계가 최소 하나 있어야 함 (통계성·코드성 엔터티는 예외)"],"t":"숫자가 나오는 특징은 '인스턴스 2개 이상', '속성 2개 이상', '관계 1개 이상'. 숫자를 바꿔서 함정을 냅니다."},"22":{"k":["유무형 분류: **유형 · 개념 · 사건**","발생 시점 분류: **기본 · 중심 · 행위**"],"w":["유형 엔터티는 유무형 분류(물리적 형태 있음: 사원, 상품)","개념 엔터티는 유무형 분류(형태 없음: 보험상품, 조직)","사건 엔터티는 유무형 분류(업무 중 발생: 주문, 청구)",""],"t":"분류 기준이 두 개라 섞어서 냅니다. '유개사' / '기중행'으로 묶어 두세요."},"23":{"k":["**행위** 엔터티: 2개 이상의 부모에서 발생, 자주 바뀌고 양이 많음 (주문내역, 이력)","기본 → 중심 → 행위 순으로 생겨남"],"w":["기본 엔터티는 부모 없이 독립적으로 생성됨 (사원, 상품)","중심 엔터티는 기본에서 발생해 업무의 중심이 됨 (주문, 계약)","","개념 엔터티는 유무형 분류로, 발생 시점 분류가 아님"],"t":"'이력', '내역', '변경'이 이름에 들어가면 행위 엔터티로 보면 됩니다."},"24":{"k":["**기본(키)** 엔터티: 다른 엔터티에서 주식별자를 상속받지 않고 **독립 생성** (사원, 부서, 상품)"],"w":["","중심 엔터티는 기본 엔터티로부터 발생","행위 엔터티는 두 개 이상의 부모에서 발생","사건 엔터티는 유무형 분류로, 업무 수행 중 발생하는 것"],"t":"'독립적', '자신의 고유한 주식별자'가 보이면 기본 엔터티입니다."},"25":{"k":["**중심** 엔터티: 기본 엔터티에서 발생, 업무의 중심, 행위 엔터티를 많이 만들어 냄 (주문, 계약)"],"w":["기본 엔터티는 부모 없이 독립 생성되는 엔터티","","행위 엔터티는 중심 엔터티에서 파생된 내역·이력","유형 엔터티는 유무형 분류로 물리적 형태가 있는 것"],"t":"흐름으로 외우세요. 고객·상품(기본) → 주문(중심) → 주문상세·배송이력(행위)."},"26":{"k":["**개념** 엔터티: 물리적 형태 없이 관리할 개념 정보 (보험상품, 조직, 계좌상품)","유형: 사원·물품 / 사건: 주문·청구"],"w":["사원은 손에 잡히는 실체가 있는 유형 엔터티","","주문은 업무 수행 중 발생하는 사건 엔터티","물품은 형태가 있는 유형 엔터티"],"t":"'보험상품'은 개념 엔터티 예시로 거의 고정 출제됩니다. 상품이라는 말에 속아 유형으로 고르지 마세요."},"27":{"k":["엔터티 명명: **현업 용어 · 약어 지양 · 단수 명사 · 유일한 이름 · 생성 의미대로**"],"w":["현업에서 쓰는 용어를 쓰는 건 명명 원칙","","단수 명사 사용은 명명 원칙","모든 엔터티에서 이름이 유일해야 함. 명명 원칙"],"t":"명명 원칙의 오답은 '약어 사용', '복수 명사', '물리 테이블명(TB_)' 셋 중 하나로 나옵니다."},"40":{"k":["엔터티 = **테이블**, 인스턴스 = **행**(튜플), 속성 = **컬럼**, 속성값 = 값"],"w":["","인스턴스와 속성의 대응이 바뀜. 인스턴스=행, 속성=컬럼","엔터티가 테이블이고 인스턴스가 행인데 순서가 뒤바뀜","엔터티는 테이블이지 컬럼이 아님"],"t":"인스턴스는 '한 건'이니 한 줄(행), 속성은 '항목'이니 한 칸 세로줄(컬럼)입니다."},"423":{"k":["유무형 분류: 유형(실체) · 개념(형태 없음) · **사건**(업무 중 발생: 주문, 수강, 예약)"],"w":["유형 엔터티는 물리적 형태가 있는 것 (사원, 물품)","개념 엔터티는 형태 없는 정보 (보험상품, 조직)","","기본 엔터티는 발생 시점 분류라 기준이 다름"],"t":"'특정 시점에 발생한 일'은 사건입니다. 문제의 분류 기준(유무형/발생 시점)을 먼저 확인하세요."},"493":{"k":["엔터티는 **인스턴스가 2개 이상**이어야 함","1건뿐이면 집합으로 관리할 의미가 없음"],"w":["고객은 여러 명을 관리하는 정상 엔터티","상품도 여러 건을 관리하는 정상 엔터티","주문은 계속 쌓이는 사건 엔터티",""],"t":"'단 하나', '1건뿐'이라는 말이 보이면 엔터티 특징(인스턴스 2개 이상) 위반입니다."},"494":{"k":["엔터티는 다른 엔터티와 **관계 1개 이상**","예외: 코드성·통계성·내부 필요 엔터티"],"w":["관계가 하나도 없으면 정상이라 보기 어려움","식별자가 있어도 관계 조건은 따로 지켜야 함","","속성 개수와 관계 조건은 별개"],"t":"관계 없는 엔터티는 '재검토' 대상입니다. 단 코드·통계성 엔터티는 예외라는 단서가 붙으면 맞는 문장."},"495":{"k":["사건 엔터티 = 업무 수행 중 **발생하는 일** (주문, 청구, 수강, 예약)"],"w":["상품은 형태가 있는 유형 엔터티","부서는 유형(또는 개념) 쪽으로 보는 엔터티로 사건이 아님","보험상품은 형태 없는 개념 엔터티",""],"t":"사건 엔터티 이름은 대개 동사에서 나온 명사입니다. 주문하다→주문, 청구하다→청구."},"496":{"k":["주문내역·주문상세는 두 부모(주문, 상품)에서 생기는 **행위** 엔터티","기본 엔터티는 독립 생성(고객, 상품)"],"w":["사원은 형태가 있는 유형 엔터티. 맞는 짝","조직은 형태 없는 개념 엔터티. 맞는 짝","","주문은 업무 중 발생하는 사건 엔터티. 맞는 짝"],"t":"'~내역', '~상세', '~이력'이 붙으면 행위 엔터티. 기본으로 짝지은 보기는 틀립니다."},"497":{"k":["엔터티 이름: **단수 명사**, 현업 용어, 약어·물리명 지양, 업무 행위(관리·처리) 붙이지 않음"],"w":["복수형('~들')은 쓰지 않음","CUST_TB 같은 약어·물리 테이블명은 피함","'관리' 같은 업무 행위를 이름에 붙이지 않음",""],"t":"가장 짧고 현업이 그대로 부르는 이름이 정답인 경우가 많습니다."},"543":{"k":["엔터티는 **관계 1개 이상**이 원칙 → '독립적으로 혼자 존재'는 오히려 반대"],"w":["업무에서 관리가 필요한지 확인하는 건 맞는 확인 사항","","인스턴스가 두 개 이상인지 확인하는 건 맞음","유일하게 식별할 수 있는지 확인하는 것도 맞음"],"t":"'다른 엔터티 없이 독립적으로'라는 표현은 엔터티 특징(관계 존재)과 충돌합니다."},"1065":{"k":["엔터티 = 영속적으로 존재하는 **인스턴스의 집합** → 2개 이상","속성 2개 이상, 업무 프로세스에서 사용"],"w":["업무에서 필요하고 관리할 정보여야 함. 맞는 특징","유일한 식별자로 식별돼야 함. 맞는 특징","관계가 최소 하나 있어야 함. 맞는 특징",""],"t":"엔터티는 '집합'입니다. 집합이라는 단어가 나오면 '하나뿐이어도 된다'는 바로 틀린 말이에요."},"1066":{"k":["**행위** 엔터티: 2개 이상 부모에서 발생, 자주 변경, 양 증가 (주문상세, 이력)"],"w":["기본 엔터티는 부모 없이 독립 생성 (고객, 상품)","중심 엔터티는 기본에서 발생한 업무 중심 (주문, 계약)","","개념 엔터티는 유무형 분류로 기준이 다름"],"t":"'두 개 이상의 부모'와 '자주 바뀜, 양이 늘어남' 조합은 행위 엔터티 정의 문구입니다."},"1067":{"k":["**개념** 엔터티 = 형태 없는 개념 정보 (조직, 보험상품)"],"w":["유형 엔터티는 물리적 형태가 있음 (사원, 물품)","행위 엔터티는 발생 시점 분류라 기준이 다름","사건 엔터티는 업무 수행 중 발생하는 것 (주문, 청구)",""],"t":"'물리적 형태는 없지만'이라는 말이 나오면 개념 엔터티입니다."},"1142":{"k":["**중심** 엔터티: 기본에서 발생 · 업무 중심 · 데이터 양 많음 · 행위 엔터티를 만들어 냄"],"w":["기본 엔터티는 독립 생성되는 부모 역할","개념 엔터티는 유무형 분류","행위 엔터티는 중심에서 파생되는 쪽",""],"t":"'행위 엔터티를 만들어 낸다'는 중심 엔터티의 정의 문구입니다. 만들어지는 쪽이 아니라 만드는 쪽."},"1185":{"k":["기본: 고객·상품 / 중심: 주문 / 행위: 주문상세·**이력**"],"w":["고객은 독립 생성되는 기본 엔터티. 맞는 분류","주문은 기본에서 발생한 중심 엔터티. 맞는 분류","주문상세는 두 부모에서 생기는 행위 엔터티. 맞는 분류",""],"t":"'이력'은 업무가 일어날 때마다 쌓이는 행위 엔터티입니다. 기본이라 하면 틀려요."},"1228":{"k":["엔터티 특징: 업무 필요 · 식별자 · 인스턴스 2+ · 업무 프로세스 사용 · **속성 2+** · 관계 1+"],"w":["속성이 두 개 이상 있어야 엔터티","인스턴스는 두 개 이상 있어야 함","관계는 하나 이상 필요 (코드성 제외 단서와 상관없이 원칙 위반)",""],"t":"숫자가 들어간 특징 세 개(인스턴스 2+, 속성 2+, 관계 1+)는 꼭 같이 외우세요."},"1275":{"k":["엔터티 이름은 **단수 명사** (고객들 ✕ → 고객)"],"w":["현업 용어 사용은 맞는 원칙","","약어를 쓰지 않는 것은 맞는 원칙","이름이 유일해야 하는 것은 맞는 원칙"],"t":"엔터티 자체가 집합이라 이름에 복수형을 또 붙이지 않습니다."},"1276":{"k":["기본(키) 엔터티: 원래 존재, **독립 생성**, 자기 주식별자 보유","부모 식별자를 상속받는 건 중심·행위 쪽"],"w":["업무에 원래 존재하는 정보. 맞는 설명","다른 엔터티와의 관계로 생기지 않고 독립 생성. 맞는 설명","자기만의 주식별자를 가짐. 맞는 설명",""],"t":"기본 엔터티 = '부모가 없다'. 상속받는다는 말이 붙으면 틀린 설명입니다."},"1325":{"k":["발생 시점: 기본 · 중심 · 행위","유무형: 유형 · 개념 · **사건**"],"w":["기본 엔터티는 발생 시점 분류","중심 엔터티는 발생 시점 분류","행위 엔터티는 발생 시점 분류",""],"t":"'사건'과 '행위'가 비슷하게 들리지만 기준이 다릅니다. 사건-유무형, 행위-발생 시점."},"1326":{"k":["주문상품 = 주문과 상품의 M:N을 푸는 엔터티, 두 부모에서 발생 → **행위** 엔터티"],"w":["고객은 기본 엔터티. 맞는 분류","상품은 기본 엔터티. 맞는 분류","","주문은 중심 엔터티. 맞는 분류"],"t":"M:N을 풀려고 만든 엔터티(주문상품, 수강신청내역)는 부모가 둘이라 행위 엔터티입니다."},"1365":{"k":["유무형 분류: 유형 · 개념 · 사건","중심 엔터티는 발생 시점 분류"],"w":["유형 엔터티는 유무형 분류","개념 엔터티는 유무형 분류","사건 엔터티는 유무형 분류",""],"t":"'유개사'(유형·개념·사건)에 없는 이름을 고르면 됩니다."},"1410":{"k":["기본 엔터티 = 원래 존재 (고객, 상품, 부서)","주문은 고객·상품에서 발생하는 **중심** 엔터티"],"w":["고객은 원래 존재하는 기본 엔터티","상품은 원래 존재하는 기본 엔터티","","부서는 원래 존재하는 기본 엔터티"],"t":"'이게 없어도 이 엔터티가 생길 수 있나?'를 물어 보세요. 주문은 고객·상품 없이는 못 생깁니다."},"1510":{"k":["기본(학생, 강좌)에서 발생 + 다른 엔터티(출석, 성적)의 부모 = **중심** 엔터티"],"w":["기본 엔터티는 다른 엔터티 없이 독립 생성","개념 엔터티는 유무형 분류","","유형 엔터티는 유무형 분류"],"t":"중심 엔터티는 '자식이기도 하고 부모이기도 한' 가운데 위치입니다."},"1513":{"k":["서비스이용 = 고객이 서비스를 쓸 때마다 쌓임 → **행위** 엔터티","개념 엔터티는 조직·보험상품처럼 형태 없는 개념"],"w":["고객은 기본 엔터티. 맞는 분류","서비스는 원래 존재하는 기본 엔터티. 맞는 분류","청구는 이용에서 파생되는 행위 엔터티. 맞는 분류",""],"t":"분류 짝 문제에서 기준이 다른 이름(개념, 사건)이 섞여 있으면 그 보기부터 의심하세요."},"1556":{"k":["발생 시점 분류에 **사건**은 없음 (사건은 유무형 분류)"],"w":["","중심 엔터티는 발생 시점 분류","행위 엔터티는 발생 시점 분류","기본 엔터티는 발생 시점 분류"],"t":"'기중행' 세 글자 밖의 이름이 답입니다."},"1603":{"k":["상품·고객·부서 = 기본 / 주문상세 = **행위**"],"w":["상품은 기본 엔터티","","부서는 기본 엔터티","고객은 기본 엔터티"],"t":"'성격이 다른 하나' 문제는 셋이 같은 분류인지 먼저 확인하면 금방 보입니다."},"1604":{"k":["엔터티: 유일한 식별자 · 인스턴스 2+ · 속성 2+ · 업무 프로세스 사용 · 관계 1+"],"w":["","업무 프로세스에서 쓰이지 않으면 엔터티로 둘 이유가 없음","식별자는 엔터티의 필수 조건","인스턴스는 두 개 이상이어야 함"],"t":"'~없어도 된다', '~하나면 충분하다'처럼 조건을 느슨하게 만드는 보기는 대부분 오답입니다."},"28":{"k":["속성 = 업무에 필요한 **더 이상 분리되지 않는 최소 단위**","한 속성은 **한 값**만, 주식별자에 **함수적 종속**"],"w":["한 속성에 여러 값이 들어가면 1정규형 위반으로 분리 대상","속성은 주식별자에 함수적으로 종속돼야 함","더 분리할 수 있다면 속성이 아니라 여러 속성으로 나눠야 함",""],"t":"속성 정의 문제는 '최소 단위', '한 개의 값', '주식별자에 종속' 세 문구를 찾으세요."},"29":{"k":["특성 분류: 기본 · 설계 · **파생**","파생 속성 = 다른 속성에서 **계산·변형** (총금액, 재고수량)"],"w":["기본 속성은 업무에서 바로 나오는 원래 속성 (단가, 수량)","설계 속성은 모델러가 새로 만든 코드·일련번호","","복합 속성은 구성 방식 분류로 여러 세부 속성으로 나뉘는 것 (주소)"],"t":"파생 속성은 원본이 바뀌면 같이 바꿔야 해서 가급적 적게 두는 게 좋습니다. 이 문장도 자주 나와요."}};
